var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u0417\u0430\u043b\u0438\u0432\u0430 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043e\u0442 \u0421\u0428\u0410 \u000d\u000a\u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0435\u0439\u0442\u0440\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u0442\u044c \u0418\u0440\u0430\u043d \u000d\u000a\u041f\u043e\u0441\u043b\u0435 \u0443\u0434\u0430\u0440\u043e\u0432 \u043f\u043e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430\u043c, \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u000d\u000a\u0438 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u043c \u043e\u0431\u044a\u0435\u043a\u0442\u0430\u043c \u0432\u0441\u0435\u0445 \u0448\u0435\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043d \u0421\u0421\u0410\u0413\u041f\u0417 \u000d\u000a\u0441\u0440\u0435\u0434\u0438 \u043b\u0438\u0434\u0435\u0440\u043e\u0432 \u0417\u0430\u043b\u0438\u0432\u0430 \u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043b\u0441\u044f \u043a\u043e\u043d\u0441\u0435\u043d\u0441\u0443\u0441: \u0421\u0428\u0410 \u000d\u000a\u0434\u043e\u043b\u0436\u043d\u044b \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u043e\u0441\u043b\u0430\u0431\u0438\u0442\u044c \u0432\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b \u000d\u000a\u0418\u0440\u0430\u043d\u0430. \u041e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043a\u043e\u043b\u043b\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0439 \u0444\u043e\u0440\u043c\u0430\u0442.\u000d\u000aS&P: \u0431\u0430\u043d\u043a\u0438 \u0417\u0430\u043b\u0438\u0432\u0430 \u0440\u0438\u0441\u043a\u0443\u044e\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u0442\u044c \u000d\u000a$307 \u043c\u043b\u0440\u0434 \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432 \u000d\u000a\u041f\u0440\u0438 \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0439 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0439 \u043e\u0442\u0442\u043e\u043a \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432 \u000d\u000a\u0438\u0437 \u0431\u0430\u043d\u043a\u043e\u0432 \u0448\u0435\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043d \u0421\u0421\u0410\u0413\u041f\u0417 \u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c \u000d\u000a$307 \u043c\u043b\u0440\u0434, \u043f\u043e\u0442\u0435\u0440\u0438 45 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0431\u0430\u043d\u043a\u043e\u0432 \u2014 $37 \u043c\u043b\u0440\u0434. \u000d\u000a\u041d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0443\u044f\u0437\u0432\u0438\u043c \u0431\u0430\u043d\u043a\u043e\u0432\u0441\u043a\u0438\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430. \u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u000d\u000a\u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 \u2014 \u0434\u0432\u0435\u2013\u0447\u0435\u0442\u044b\u0440\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u0438\u043d\u0442\u0435\u043d\u0441\u0438\u0432\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430.\u000d\u000aEGA \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0447\u0435\u0440\u0435\u0437 \u041e\u043c\u0430\u043d: \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0439 \u2014 \u043d\u0430 \u0447\u0435\u0442\u044b\u0440\u0435\u0445\u043b\u0435\u0442\u043d\u0435\u043c \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0435 \u000d\u000aEmirates Global Aluminium \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0438\u043c\u043f\u043e\u0440\u0442 \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430 \u000d\u000a\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0433\u043e\u0442\u043e\u0432\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0447\u0435\u0440\u0435\u0437 \u043f\u043e\u0440\u0442 \u0421\u043e\u0445\u0430\u0440, \u043e\u0442\u043a\u0443\u0434\u0430 \u000d\u000a\u0441\u044b\u0440\u044c\u0435 \u0432\u0435\u0437\u0443\u0442 \u043f\u043e \u0441\u0443\u0448\u0435 \u043d\u0430 \u0437\u0430\u0432\u043e\u0434\u044b \u0432 \u041e\u0410\u042d. \u0426\u0435\u043d\u044b \u043d\u0430 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0439 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 $3546,5 \u0437\u0430 \u0442\u043e\u043d\u043d\u0443 (+12% \u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430). \u0420\u0435\u0433\u0438\u043e\u043d \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 ~9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043e\u0431\u044a\u0435\u043c\u0430, \u000d\u000a80% \u0438\u0434\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442.\u000d\u000a\u0421\u0428\u0410 \u0438\u043d\u0438\u0446\u0438\u0438\u0440\u043e\u0432\u0430\u043b\u0438 \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0435 \u000d\u000a\u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0442\u0438\u0432 \u041a\u0438\u0442\u0430\u044f\u000d\u000a\u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d \u043e\u0431\u0432\u0438\u043d\u044f\u0435\u0442 \u041f\u0435\u043a\u0438\u043d \u0432 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u0437\u0430 \u0441\u0447\u0435\u0442 \u0438\u0437\u0431\u044b\u0442\u043e\u0447\u043d\u044b\u0445 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439, \u0432\u044b\u0442\u0435\u0441\u043d\u044f\u044e\u0449\u0438\u0445 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439. \u0420\u0430\u0437\u0431\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u0443\u0442\u044c \u043a \u043d\u043e\u0432\u044b\u043c \u0442\u0430\u0440\u0438\u0444\u0430\u043c \u0438 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u043c \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u043c.\u000d\u000aMacquarie \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0432 2026 \u0433\u043e\u0434\u0443 \u000d\u000a\u0411\u0430\u043d\u043a \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0435\u043b \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u0441 \u043f\u0440\u043e\u0444\u0438\u0446\u0438\u0442\u0430 90 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u0434\u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0433\u043e \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430. \u041f\u0440\u0438\u0447\u0438\u043d\u044b: \u0430\u0432\u0430\u0440\u0438\u044f \u0432 Morowali, \u000d\u000a\u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0430 \u043b\u0438\u043c\u043e\u043d\u0438\u0442\u0430 \u0438 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u0441 \u0441\u0435\u0440\u043e\u0439 \u0441 \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u000d\u000a\u0412\u043e\u0441\u0442\u043e\u043a\u0430. \u0412\u044b\u043f\u0443\u0441\u043a \u0444\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u044f\u043d\u0432\u0430\u0440\u0435 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 \u0443\u0436\u0435 \u000d\u000a\u0443\u043f\u0430\u043b \u043d\u0430 10% \u0433\u043e\u0434 \u043a \u0433\u043e\u0434\u0443.\u000d\u000a\u041e\u0410\u042d \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u044e\u0442 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u043c\u0438\u0441\u0441\u0438\u0438 \u043f\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0414\u0438\u043f\u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u041e\u0410\u042d \u0410\u043d\u0432\u0430\u0440 \u0413\u0430\u0440\u0433\u0430\u0448 \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u043c \u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0438 \u043a \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0421\u0428\u0410. \u000d\u000a\u041f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442\u0441\u044f, \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0430 \u043d\u0435\u0442. \u000d\u000a\u0420\u044f\u0434 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0430 \u0443\u0436\u0435 \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c, \u000d\u000a\u043a\u0440\u0438\u0442\u0438\u043a\u0443\u044f \u043d\u0430\u0447\u0430\u043b\u043e \u0432\u043e\u0439\u043d\u044b \u0431\u0435\u0437 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u0439.\u000d\u000a\u0426\u0411 \u041e\u0410\u042d \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0441\u043e \u0432\u0440\u0435\u043c\u0435\u043d \u000d\u000a\u043f\u0430\u043d\u0434\u0435\u043c\u0438\u0438 \u043f\u0430\u043a\u0435\u0442 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u0431\u0430\u043d\u043a\u043e\u0432 \u000d\u000a\u0411\u0430\u043d\u043a\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0442 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u043c (\u0434\u043e 30% \u000d\u000a\u043e\u0442 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439) \u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0430\u043c \u000d\u000a\u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u0432 \u0434\u0438\u0440\u0445\u0430\u043c\u0430\u0445 \u0438 \u0434\u043e\u043b\u043b\u0430\u0440\u0430\u0445. \u0420\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u000d\u000a\u0441\u043c\u044f\u0433\u0447\u0438\u043b \u043d\u043e\u0440\u043c\u0430\u0442\u0438\u0432\u044b \u043f\u043e \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438. Goldman Sachs \u000d\u000a\u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u0438\u0440\u043e\u0441\u0442 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0431\u0443\u0444\u0435\u0440\u043e\u0432 \u0434\u043e 3 \u043f. \u043f.\u000d\u000aAlba \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u043d\u0430 19% \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u0442\u0440\u0438 \u0438\u0437 \u0448\u0435\u0441\u0442\u0438 \u043b\u0438\u043d\u0438\u0439 \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0438\u0437\u0430 \u0438\u0437 \u0437\u0430 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0438 \u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0438 \u0441\u044b\u0440\u044c\u044f, \u043e\u0431\u044a\u044f\u0432\u0438\u0432 \u0444\u043e\u0440\u0441 \u043c\u0430\u0436\u043e\u0440. \u041f\u0440\u043e\u0441\u0442\u043e\u0439 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d \u0434\u043b\u044f \u0442\u0435\u0445\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u044f. \u041c\u043e\u0449\u043d\u043e\u0441\u0442\u044c Alba \u2014 \u000d\u000a1,62 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434.\u000d\u000a\u0422\u0440\u0435\u0442\u044c \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 HPAL-\u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a\u0432\u0441\u0442\u0430\u043b\u0430 \u043f\u043e\u0441\u043b\u0435 \u0430\u0432\u0430\u0440\u0438\u0438 \u0432 Morowali \u000d\u000a\u0427\u0435\u0442\u044b\u0440\u0435 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 GEM \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043e\u0431\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u0434\u0430\u043c\u0431\u044b \u0445\u0432\u043e\u0441\u0442\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430. \u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u2014 \u000d\u000aQMB New Energy Materials (\u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u044b: CATL, Ecopro \u000d\u000a\u0438 \u0434\u0440.) \u2014 \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u044f\u0442\u044c \u0434\u043e \u0442\u0440\u0435\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u041d\u0430 \u044d\u0442\u0438 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f 30% \u0432\u0441\u0435\u0445 HPAL \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u0432\u0438\u0437\u0438\u0442 \u0432 \u041a\u0438\u0442\u0430\u0439 \u2028\u000d\u000a\u0438\u0437 \u0437\u0430 \u0432\u043e\u0439\u043d\u044b \u0432 \u0418\u0440\u0430\u043d\u0435 \u000d\u000a\u041f\u0435\u0440\u0432\u0430\u044f \u043f\u043e\u0435\u0437\u0434\u043a\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0421\u0428\u0410 \u0432 \u041a\u041d\u0420 \u000d\u000a\u0441 2017 \u0433\u043e\u0434\u0430 \u043c\u043e\u0436\u0435\u0442 \u0441\u0434\u0432\u0438\u043d\u0443\u0442\u044c\u0441\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u043c\u0435\u0441\u044f\u0446. \u000d\u000a\u041f\u0435\u0440\u0435\u043d\u043e\u0441 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u000d\u000a\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f\u0445 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0443\u0436\u0435 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f.\u000d\u000a01 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000aEGA \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0447\u0435\u0440\u0435\u0437 \u041e\u043c\u0430\u043d \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u0412\u043e\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043c\u0435\u0436\u0434\u0443 \u0421\u0428\u0410, \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c \u0438 \u0418\u0440\u0430\u043d\u043e\u043c \u0432\u044b\u043d\u0443\u0436\u0434\u0430\u0435\u0442 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u0438\u0441\u043a\u0430\u0442\u044c \u000d\u000a\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a. \u0426\u0435\u043d\u044b \u043d\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0439 \u0442\u0435\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0435\u043c \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 \u000d\u000a\u0447\u0435\u0442\u044b\u0440\u0435\u0445\u043b\u0435\u0442\u043d\u0435\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u2014 $3546,5 \u0437\u0430 \u0442\u043e\u043d\u043d\u0443, \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u0432 \u043e\u043a\u043e\u043b\u043e 12% \u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430. \u000d\u000aEmirates Global Aluminium (EGA) \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u0438\u0442 \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438 \u0438\u043c\u043f\u043e\u0440\u0442 \u0441\u044b\u0440\u044c\u044f \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u043e\u043c\u0430\u043d\u0441\u043a\u0438\u0439 \u043f\u043e\u0440\u0442 \u0421\u043e\u0445\u0430\u0440 \u2014 \u043e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u000d\u000aReuters. \u0421\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u043e \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u000d\u000a\u043f\u0430\u0440\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043e.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u043e \u043f\u0435\u0440\u0435\u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0443\u044e\u0442 \u000d\u000a\u0433\u0440\u0443\u0437\u044b \u043d\u0430 \u043f\u043e\u0440\u0442\u044b \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u0417\u0430\u043b\u0438\u0432\u0430 \u2014 \u0421\u043e\u0445\u0430\u0440 \u000d\u000a\u0438 \u0424\u0443\u0434\u0436\u0435\u0439\u0440\u0443, \u043e\u0442\u043a\u0443\u0434\u0430 \u0442\u043e\u0432\u0430\u0440\u044b \u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u000d\u000a\u043d\u0430\u0437\u0435\u043c\u043d\u044b\u043c \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043e\u043c. EGA \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u000d\u000a\u0437\u0430\u0432\u043e\u0437\u0438\u0442\u044c \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c \u0447\u0435\u0440\u0435\u0437 \u0421\u043e\u0445\u0430\u0440 \u000d\u000a\u0438 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0435\u0433\u043e \u043f\u043e \u0441\u0443\u0448\u0435 \u043d\u0430 \u0437\u0430\u0432\u043e\u0434\u044b \u000d\u000a\u0432 \u0414\u0443\u0431\u0430\u0435 \u0438 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438, \u0430 \u043e\u0442\u0433\u0440\u0443\u0437\u043a\u0430 \u0433\u043e\u0442\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0447\u0435\u0440\u0435\u0437 \u0442\u043e\u0442 \u0436\u0435 \u043f\u043e\u0440\u0442 \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0430\u0447\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u043d\u0430 \u044d\u0442\u043e\u0439 \u043d\u0435\u0434\u0435\u043b\u0435. \u000a\u000d\u000aEGA \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 2,7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0433\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0433\u043e\u0434. \u0420\u0435\u0433\u0438\u043e\u043d \u0432 \u0446\u0435\u043b\u043e\u043c \u000d\u000a\u0434\u0430\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u2014 \u043e\u043a\u043e\u043b\u043e 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430, \u043f\u0440\u0438\u0447\u0435\u043c \u0434\u043e 80% \u0438\u0434\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442, \u000d\u000a\u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0432 \u0421\u0428\u0410 \u0438 \u0415\u0432\u0440\u043e\u043f\u0443. \u0421\u0445\u043e\u0436\u0438\u0435 \u000d\u000a\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u0438 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Alba (1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434), \u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u0432\u0448\u0430\u044f \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u0438\u0437-\u0437\u0430 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430.\u000d\u000a02 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u041e\u0410\u042d \u043c\u043e\u0433\u0443\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u043c\u0438\u0441\u0441\u0438\u0438 \u0421\u0428\u0410 \u000d\u000a\u043f\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u043d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u043e\u0440\u0441\u043a\u0438\u0445 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432 \u043c\u0438\u0440\u0430, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 20% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043d\u0435\u0444\u0442\u044c\u044e. \u0418\u0440\u0430\u043d \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b \u043f\u0440\u043e\u043b\u0438\u0432 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043d\u0430\u0447\u0430\u043b\u0430 \u0432\u043e\u0439\u043d\u044b \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000d\u000a\u041e\u0410\u042d \u043c\u043e\u0433\u0443\u0442 \u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u044c\u0441\u044f \u043a \u0443\u0441\u0438\u043b\u0438\u044f\u043c \u0421\u0428\u0410 \u000d\u000a\u043f\u043e \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435 \u043d\u0430 \u0444\u043e\u043d\u0435 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0441 \u0418\u0440\u0430\u043d\u043e\u043c. \u041e\u0431 \u044d\u0442\u043e\u043c \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0410\u043d\u0432\u0430\u0440 \u0413\u0430\u0440\u0433\u0430\u0448.\u000a\u000d\u000a\u041f\u043e \u0435\u0433\u043e \u0441\u043b\u043e\u0432\u0430\u043c, \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u043c \u000d\u000a\u0443\u0447\u0430\u0441\u0442\u0438\u0438 \u041e\u0410\u042d \u0432 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442\u0441\u044f, \u000d\u000a\u043e\u0434\u043d\u0430\u043a\u043e \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0430 \u043f\u043e\u043a\u0430 \u000d\u000a\u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442. \u0413\u0430\u0440\u0433\u0430\u0448 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u043d\u0443\u043b, \u0447\u0442\u043e \u000d\u000a\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0437\u0430 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0431\u0435\u0441\u043f\u0435\u0440\u0435\u0431\u043e\u0439\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u044d\u043d\u0435\u0440\u0433\u0438\u0438 \u0438 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u000d\u000a\u043b\u0435\u0436\u0438\u0442 \u043d\u0430 \u00ab\u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445\u00bb \u0410\u0437\u0438\u0438, \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u000d\u000a\u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u0438 \u0415\u0432\u0440\u043e\u043f\u044b.\u000a\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043f\u0440\u0438\u0437\u044b\u0432\u044b \u0414\u043e\u043d\u0430\u043b\u044c\u0434\u0430 \u0422\u0440\u0430\u043c\u043f\u0430 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u043a\u043e\u0440\u0430\u0431\u043b\u0438 \u0434\u043b\u044f \u000d\u000a\u0441\u043e\u043f\u0440\u043e\u0432\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0442\u0430\u043d\u043a\u0435\u0440\u043e\u0432, \u0440\u044f\u0434 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u0432 \u000d\u000a\u0421\u0428\u0410 \u0443\u0436\u0435 \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0438\u0441\u044c \u043e\u0442 \u0443\u0447\u0430\u0441\u0442\u0438\u044f \u0432 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438, \u000d\u000a\u043a\u0440\u0438\u0442\u0438\u043a\u0443\u044f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u0438 \u0438\u0437\u0440\u0430\u0438\u043b\u044c\u0441\u043a\u0438\u0435 \u0432\u043b\u0430\u0441\u0442\u0438 \u000d\u000a\u0437\u0430 \u043d\u0430\u0447\u0430\u043b\u043e \u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0431\u0435\u0437 \u000d\u000a\u043f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u0439.\u000d\u000a\u0414\u043b\u044f \u041e\u0410\u042d \u2014 \u043a\u0440\u0443\u043f\u043d\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435\u0440\u0430 \u043d\u0435\u0444\u0442\u0438 \u000d\u000a\u0438 \u0432\u0430\u0436\u043d\u043e\u0433\u043e \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0445\u0430\u0431\u0430 \u2014 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u0438\u043c\u0435\u0435\u0442 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u000d\u000a\u0418\u0440\u0430\u043d \u0443\u0436\u0435 \u043d\u0430\u043d\u043e\u0441\u0438\u043b \u0443\u0434\u0430\u0440\u044b \u043f\u043e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u000d\u000a\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u043c\u044b\u0435 \u0434\u043b\u044f \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043d\u0435\u0444\u0442\u0438.\u000a\u000d\u000a\u0413\u0430\u0440\u0433\u0430\u0448 \u043e\u0442\u043c\u0435\u0442\u0438\u043b, \u0447\u0442\u043e \u041e\u0410\u042d \u043e\u0436\u0438\u0434\u0430\u043b\u0438 \u000d\u000a\u00ab\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u044b\u0445 \u0430\u0442\u0430\u043a\u00bb \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0418\u0440\u0430\u043d\u0430 \u0432 \u0441\u043b\u0443\u0447\u0430\u0435 \u000d\u000a\u043f\u0440\u043e\u0432\u0430\u043b\u0430 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u043f\u043e \u044f\u0434\u0435\u0440\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0435, \u000d\u000a\u043e\u0434\u043d\u0430\u043a\u043e \u043c\u0430\u0441\u0448\u0442\u0430\u0431 \u0442\u0435\u043a\u0443\u0449\u0438\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u043f\u0440\u0435\u0432\u0437\u043e\u0448\u0435\u043b \u000d\u000a\u043f\u0440\u043e\u0433\u043d\u043e\u0437\u044b \u0438 \u0442\u0435\u043f\u0435\u0440\u044c \u043d\u043e\u0441\u0438\u0442 \u00ab\u043f\u043e\u043b\u043d\u043e\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u044b\u0439 \u000d\u000a\u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u00bb.\u000a\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043e\u043d\u043d\u043e \u0442\u0435\u0441\u043d\u044b\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0435 \u000d\u000a\u0441\u0432\u044f\u0437\u0438 \u0441 \u0418\u0440\u0430\u043d\u043e\u043c, \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438 \u000d\u000a\u0443\u0445\u0443\u0434\u0448\u0438\u043b\u0438\u0441\u044c \u043f\u043e\u0441\u043b\u0435 \u043d\u0430\u0447\u0430\u043b\u0430 \u0431\u043e\u0435\u0432\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. \u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0413\u0430\u0440\u0433\u0430\u0448\u0430, \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0434\u0438\u0430\u043b\u043e\u0433\u0430 \u0441 \u000d\u000a\u0438\u0441\u043b\u0430\u043c\u0441\u043a\u043e\u0439 \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0439 \u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u043d\u0435 \u000d\u000a\u0432\u0435\u0434\u0435\u0442\u0441\u044f.\u000d\u000a03 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u044e\u0442 \u0421\u0428\u0410 \u000d\u000a\u043d\u0435\u0439\u0442\u0440\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u0442\u044c \u0418\u0440\u0430\u043d \u043d\u0430 \u0444\u043e\u043d\u0435 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430\u000d\u000a\u041a\u0440\u0438\u0437\u0438\u0441 \u0441\u0442\u0430\u0432\u0438\u0442 \u043f\u043e\u0434 \u0443\u0433\u0440\u043e\u0437\u0443 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c \u0440\u0435\u0433\u0438\u043e\u043d\u0430, \u043d\u043e \u0438 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u0440\u044b\u043d\u043a\u0438. \u0422\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u043a \u0421\u0428\u0410 \u00ab\u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0440\u0435\u0448\u0438\u0442\u044c \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0439 \u0432\u043e\u043f\u0440\u043e\u0441\u00bb \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u0440\u0438\u0441\u043a\u0438 \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u043e\u0439 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438. \u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0441\u0442\u0440\u0435\u043c\u044f\u0442\u0441\u044f \u0438\u0437\u0431\u0435\u0436\u0430\u0442\u044c \u043f\u0440\u044f\u043c\u043e\u0433\u043e \u0432\u043e\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f \u000d\u000a\u0432 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442.\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u044e\u0442 \u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0421\u0428\u0410, \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u044f \u000d\u000a\u043d\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u0442\u0435\u043a\u0443\u0449\u0438\u043c\u0438 \u0432\u043e\u0435\u043d\u043d\u044b\u043c\u0438 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f\u043c\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430 \u0438 \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u000d\u000a\u043b\u0438\u0448\u0438\u0442\u044c \u0435\u0433\u043e \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u0438 \u0443\u0433\u0440\u043e\u0436\u0430\u0442\u044c \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0430\u043c \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e Reuters \u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u043d\u0430 \u000d\u000a\u0434\u0438\u043f\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438.\u000a\u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043d\u0438\u043a\u043e\u0432 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430, \u000d\u000a\u0430\u0440\u0430\u0432\u0438\u0439\u0441\u043a\u0438\u0435 \u043c\u043e\u043d\u0430\u0440\u0445\u0438\u0438 \u0438\u0437\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u043e \u043d\u0435 \u000d\u000a\u043f\u0440\u0438\u0437\u044b\u0432\u0430\u043b\u0438 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d \u043a \u0432\u043e\u0439\u043d\u0435, \u043e\u0434\u043d\u0430\u043a\u043e \u000d\u000a\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u044f \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u0430\u0442\u0430\u043a\u0438 \u000d\u000a\u043d\u0430 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0441\u0442\u0440\u0430\u043d \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u0440\u0430\u0434\u0438\u043a\u0430\u043b\u044c\u043d\u043e \u000d\u000a\u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438 \u0438\u0445 \u043f\u043e\u0437\u0438\u0446\u0438\u044e.\u000a\u000d\u000a\u0418\u0440\u0430\u043d \u0443\u0436\u0435 \u043f\u0440\u043e\u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043b \u0441\u0432\u043e\u0438 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438, \u043d\u0430\u043d\u0435\u0441\u044f \u0443\u0434\u0430\u0440\u044b \u043f\u043e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430\u043c, \u000d\u000a\u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u0438 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u043c \u000d\u000a\u043e\u0431\u044a\u0435\u043a\u0442\u0430\u043c \u0432\u043e \u0432\u0441\u0435\u0445 \u0448\u0435\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u0421\u043e\u0432\u0435\u0442\u0430 \u000d\u000a\u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0430\u0440\u0430\u0431\u0441\u043a\u0438\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430\u0440\u0443\u0448\u0438\u0432 \u000d\u000a\u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u043e \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432.\u000a\u000d\u000a\u0410\u0442\u0430\u043a\u0438 \u0443\u0441\u0438\u043b\u0438\u043b\u0438 \u043e\u043f\u0430\u0441\u0435\u043d\u0438\u044f, \u043a\u0430\u0441\u0430\u044e\u0449\u0438\u0435\u0441\u044f \u000d\u000a\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u0430 \u0418\u0440\u0430\u043d\u0430 \u000d\u000a\u0438 \u0443\u0433\u0440\u043e\u0437\u044b \u0440\u0435\u0433\u0438\u043e\u043d\u0443 \u0441 \u0435\u0433\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b. \u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u000d\u000a\u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432, \u0441\u0440\u0435\u0434\u0438 \u043b\u0438\u0434\u0435\u0440\u043e\u0432 \u0441\u0442\u0440\u0430\u043d \u000d\u000a\u0417\u0430\u043b\u0438\u0432\u0430 \u0444\u043e\u0440\u043c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u043e\u043d\u0441\u0435\u043d\u0441\u0443\u0441, \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u0421\u0428\u0410 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u043e\u0441\u043b\u0430\u0431\u0438\u0442\u044c \u000d\u000a\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u0418\u0440\u0430\u043d\u0430 \u0432\u0435\u0441\u0442\u0438 \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b.\u000a\u000d\u000a\u0412 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u000d\u000a\u0441\u0442\u0430\u043b\u043a\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0441\u043e \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0434\u0438\u043b\u0435\u043c\u043c\u043e\u0439. \u000d\u000a\u0421 \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u2014 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c \u000d\u000a\u043d\u0430 \u0443\u0433\u0440\u043e\u0437\u044b, \u0441 \u0434\u0440\u0443\u0433\u043e\u0439 \u2014 \u0440\u0438\u0441\u043a \u0431\u044b\u0442\u044c \u0432\u0442\u044f\u043d\u0443\u0442\u044b\u043c\u0438 \u000d\u000a\u0432 \u043f\u043e\u043b\u043d\u043e\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u0443\u044e \u0432\u043e\u0439\u043d\u0443. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u000d\u000a\u043f\u043e\u0434\u0447\u0435\u0440\u043a\u0438\u0432\u0430\u044e\u0442, \u0447\u0442\u043e \u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0435 \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u044b, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043b\u044e\u0431\u043e\u0435 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u000d\u000a\u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0444\u043e\u0440\u043c\u0430\u0442\u0435 \u043a\u043e\u043b\u043b\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0445 \u0443\u0441\u0438\u043b\u0438\u0439, \u000d\u000a\u0441\u043d\u0438\u0436\u0430\u044e\u0449\u0438\u0445 \u0440\u0438\u0441\u043a \u043e\u0442\u0432\u0435\u0442\u043d\u044b\u0445 \u0443\u0434\u0430\u0440\u043e\u0432.\u000d\u000a04 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000aS&P \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0434\u0438\u043b\u043e \u043e \u0440\u0438\u0441\u043a\u0435 \u043e\u0442\u0442\u043e\u043a\u0430 \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432 \u000d\u000a\u0438\u0437 \u0431\u0430\u043d\u043a\u043e\u0432 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043d\u0430 $307 \u043c\u043b\u0440\u0434 \u000d\u000a\u0412\u043e\u0435\u043d\u043d\u044b\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043e\u043a\u0430\u0437\u0430\u043b\u0438 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u0441\u043a\u0438\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0432 \u041e\u0410\u042d \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u0418\u0440\u0430\u043d \u000d\u000a\u043f\u0440\u0438\u0433\u0440\u043e\u0437\u0438\u043b \u0430\u0442\u0430\u043a\u043e\u0432\u0430\u0442\u044c \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0446\u0435\u043d\u0442\u0440\u044b \u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0438\u043d\u0441\u0442\u0438\u0442\u0443\u0442\u044b, \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0435 \u0441 \u0421\u0428\u0410 \u000d\u000a\u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c.\u000d\u000a\u0411\u0430\u043d\u043a\u043e\u0432\u0441\u043a\u0438\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u043c\u043e\u0436\u0435\u0442 \u0441\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044c\u0441\u044f \u0441 \u043e\u0442\u0442\u043e\u043a\u043e\u043c \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432 \u000d\u000a\u043d\u0430 \u0441\u0443\u043c\u043c\u0443 \u0434\u043e $307 \u043c\u043b\u0440\u0434 \u0432 \u0441\u043b\u0443\u0447\u0430\u0435 \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0439 \u000d\u000a\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0435\u0442\u0435 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430 S&P Global Ratings.\u000a\u000d\u000a\u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 S&P \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442, \u000d\u000a\u0447\u0442\u043e \u043d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0438\u043d\u0442\u0435\u043d\u0441\u0438\u0432\u043d\u0430\u044f \u0444\u0430\u0437\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u043f\u0440\u043e\u0434\u043b\u0438\u0442\u0441\u044f \u043e\u0442 \u0434\u0432\u0443\u0445 \u0434\u043e \u0447\u0435\u0442\u044b\u0440\u0435\u0445 \u043d\u0435\u0434\u0435\u043b\u044c. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u000d\u000a\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u0437\u043d\u0430\u0435\u0442 \u0440\u0438\u0441\u043a \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0445 \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0439 \u0432 \u0432\u0438\u0434\u0435 \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442\u043e\u0432, \u000d\u000a\u0441\u0442\u0430\u0432\u044f\u0449\u0438\u0445 \u043f\u043e\u0434 \u0443\u0433\u0440\u043e\u0437\u0443 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432.\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u0441\u0442\u0440\u0435\u0441\u0441-\u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044e S&P, \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u000d\u000a\u043e\u0442\u0442\u043e\u043a \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432 \u0432 \u0431\u0430\u043d\u043a\u043e\u0432\u0441\u043a\u0438\u0445 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0445 \u0448\u0435\u0441\u0442\u0438 \u000d\u000a\u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c \u000d\u000a$307 \u043c\u043b\u0440\u0434. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u0431\u0430\u043d\u043a\u0438 \u0440\u0430\u0441\u043f\u043e\u043b\u0430\u0433\u0430\u044e\u0442 \u000d\u000a\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0437\u0430\u043f\u0430\u0441\u043e\u043c \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438. \u041d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u000d\u000a\u0443\u044f\u0437\u0432\u0438\u043c\u044b\u043c\u0438 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0440\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438 \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0438\u0437-\u0437\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0434\u043e\u043b\u0433\u0430.\u000a\u000d\u000a\u0412 \u0441\u0442\u0440\u0435\u0441\u0441-\u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0438, \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u044e\u0449\u0435\u043c \u0440\u043e\u0441\u0442 \u0434\u043e\u043b\u0438 \u000d\u000a\u043f\u0440\u043e\u0431\u043b\u0435\u043c\u043d\u044b\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432 \u0434\u043e 7% \u0438\u043b\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0438\u0445 \u043e\u0431\u044a\u0435\u043c\u0430 \u043d\u0430 50%, \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0435 \u043f\u043e\u0442\u0435\u0440\u0438 \u000d\u000a45 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0431\u0430\u043d\u043a\u043e\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u043c\u043e\u0433\u0443\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c \u000d\u000a$37 \u043c\u043b\u0440\u0434.\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u041e\u0410\u042d \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0441 \u043f\u0430\u043d\u0434\u0435\u043c\u0438\u0438 \u043f\u0430\u043a\u0435\u0442 \u000d\u000a\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u0431\u0430\u043d\u043a\u043e\u0432 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u0432\u043e\u043a\u0440\u0443\u0433 \u0418\u0440\u0430\u043d\u0430 \u000d\u000a\u041c\u0435\u0440\u044b \u043f\u043e\u0437\u0438\u0442\u0438\u0432\u043d\u043e \u043f\u043e\u0432\u043b\u0438\u044f\u044e\u0442 \u043d\u0430 \u0440\u044b\u043d\u043e\u043a, \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432 \u0431\u0430\u043d\u043a\u0430\u043c \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u044c \u0438 \u0433\u0438\u0431\u043a\u043e\u0441\u0442\u044c. \u041e\u0441\u043b\u0430\u0431\u043b\u0435\u043d\u0438\u0435 \u000d\u000a\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u043a \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0443 \u043c\u043e\u0436\u0435\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0431\u0443\u0444\u0435\u0440\u044b \u0431\u0430\u043d\u043a\u043e\u0432 \u0434\u043e 3 \u043f. \u043f., \u0447\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c \u000d\u000a\u0432\u044b\u0434\u0430\u0447\u0443 \u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432.\u000d\u000a\u0426\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u0430\u043d\u043a \u041e\u0410\u042d \u043e\u0431\u044a\u044f\u0432\u0438\u043b \u043e \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u043e\u043c \u000d\u000a\u043f\u0430\u043a\u0435\u0442\u0435 \u043c\u0435\u0440 \u043f\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0431\u0430\u043d\u043a\u043e\u0432\u0441\u043a\u043e\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u043c \u0441\u043e \u0432\u0440\u0435\u043c\u0435\u043d \u000d\u000a\u043f\u0430\u043d\u0434\u0435\u043c\u0438\u0438 COVID-19. \u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u0440\u0430\u0441\u0442\u0443\u0449\u0435\u0433\u043e \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u2028\u000d\u000a\u0438\u0437-\u0437\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0435\u0433\u043e\u0441\u044f \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432\u043e\u043a\u0440\u0443\u0433 \u000d\u000a\u0418\u0440\u0430\u043d\u0430.\u000a\u000d\u000a\u0412 \u0440\u0430\u043c\u043a\u0430\u0445 \u043d\u043e\u0432\u043e\u0433\u043e \u043f\u0430\u043a\u0435\u0442\u0430 \u0431\u0430\u043d\u043a\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0442 \u000d\u000a\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u043c \u0434\u043e 30% \u000d\u000a\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u044b\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439, \u0430 \u0442\u0430\u043a\u0436\u0435\u000d\u000a\u043a \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0430\u043c \u0441\u0440\u043e\u0447\u043d\u043e\u0439 \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0432 \u0434\u0438\u0440\u0445\u0430\u043c\u0430\u0445 \u0438 \u0434\u043e\u043b\u043b\u0430\u0440\u0430\u0445. \u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u000d\u000a\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0441\u043c\u044f\u0433\u0447\u0438\u043b \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u043e \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0438 \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u043c\u0443 \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430, \u043e\u0431\u0449\u0438\u0439 \u043e\u0431\u044a\u0435\u043c \u000d\u000a\u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u0431\u0430\u043d\u043a\u043e\u0432 \u0432 \u041e\u0410\u042d, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0440\u0435\u0437\u0435\u0440\u0432\u044b \u000d\u000a\u0438 \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b, \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a$250 \u043c\u043b\u0440\u0434. \u0418\u0437 \u043d\u0438\u0445 \u0431\u043e\u043b\u0435\u0435 $109 \u043c\u043b\u0440\u0434 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u000d\u000a\u043d\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u044b\u0435 \u0431\u0430\u043b\u0430\u043d\u0441\u044b \u0432 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u043c \u0431\u0430\u043d\u043a\u0435.\u000d\u000a05 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Alba \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 19% \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u0412\u043e\u0439\u043d\u0430 \u0432 \u0418\u0440\u0430\u043d\u0435 \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u0435\u0440\u044c\u0435\u0437\u043d\u043e\u0435 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043c\u0438\u0440\u043e\u0432\u044b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f. \u0415\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u000d\u000a\u0431\u043e\u043b\u0435\u0435 5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u0435\u0442\u0430\u043b\u043b\u0430, \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0430 \u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430\u0445 \u0441\u0442\u0440\u0430\u043d \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430, \u000d\u000a\u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Aluminium Bahrain \u000d\u000a(Alba) \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043e \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430, \u0437\u0430\u043a\u0440\u044b\u0432 \u0442\u0440\u0438 \u043b\u0438\u043d\u0438\u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0438\u0437\u0430, \u000d\u000a\u0447\u0442\u043e \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 19% \u0435\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439. \u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u0434\u043b\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u000d\u000a\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u0438 \u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u043f\u0440\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0435\u0439\u0441\u044f \u000d\u000a\u0431\u043b\u043e\u043a\u0430\u0434\u0435 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0442\u043e\u0447\u043d\u0438\u043b\u0430, \u0447\u0442\u043e \u0440\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u000d\u000a\u043e \u00ab\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u043e\u0439 \u0438 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435\u00bb \u000d\u000a\u043f\u0435\u0440\u0432\u044b\u0445 \u0442\u0440\u0435\u0445 \u043b\u0438\u043d\u0438\u0439. \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u000d\u000a\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u000d\u000a\u0441\u044b\u0440\u044c\u044f \u0438 \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0438\u0442\u044c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u000d\u000a\u043d\u0430 \u043e\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044f \u0442\u0440\u0435\u0445 \u043b\u0438\u043d\u0438\u044f\u0445.\u000d\u000aAlba \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 1,62 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u0432 \u0433\u043e\u0434. \u0420\u0430\u043d\u0435\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440, \u000d\u000a\u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0431\u043b\u043e\u043a\u0430\u0434\u0430 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u043b\u0430 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043e\u0442\u0433\u0440\u0443\u0436\u0430\u0442\u044c \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e \u000d\u000a\u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c. \u041a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0442\u0440\u043e\u043d\u0443\u043b \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430 \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f \u0434\u043b\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f.\u000a\u000d\u000a\u0412 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043e\u0442\u043c\u0435\u0442\u0438\u043b\u0438, \u0447\u0442\u043e \u043f\u0435\u0440\u0438\u043e\u0434 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d \u0434\u043b\u044f \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0438 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u043a \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u043c\u0443 \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u043a\u0443 \u043f\u043e\u0441\u043b\u0435 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a\u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438. Alba \u0442\u0430\u043a\u0436\u0435 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u000d\u000a\u0441 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430\u043c\u0438 \u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c\u0438 \u0434\u043b\u044f \u043c\u0438\u043d\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0439 \u0441\u0431\u043e\u0435\u0432. \u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Bapco \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441 \u043c\u0430\u0436\u043e\u0440 \u000d\u000a\u043f\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c\u000d\u000a\u041d\u0435\u0444\u0442\u044f\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Bapco \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 380 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u043d\u0435\u0444\u0442\u0438 \u0432 \u0441\u0443\u0442\u043a\u0438. \u041e\u043d\u0430 \u000d\u000a\u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u043d\u0435\u0444\u0442\u044c \u0438\u0437 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u043f\u043e \u0442\u0440\u0443\u0431\u043e\u043f\u0440\u043e\u0432\u043e\u0434\u0443, \u0441\u043e\u0435\u0434\u0438\u043d\u044f\u044e\u0449\u0435\u043c\u0443 \u0434\u0432\u0435 \u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000a\u0418\u0440\u0430\u043d \u0430\u0442\u0430\u043a\u043e\u0432\u0430\u043b \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u043c \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u000d\u000a\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u0437\u0430\u0432\u043e\u0434 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Bapco. \u041d\u0430 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0438 \u0432\u043e\u0437\u043d\u0438\u043a \u000d\u000a\u0441\u0438\u043b\u044c\u043d\u044b\u0439 \u043f\u043e\u0436\u0430\u0440.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440, \u0447\u0442\u043e \u000d\u000a\u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0435\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438. \u000d\u000a\u0412 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 Bapco \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f, \u0447\u0442\u043e \u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0443 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u00ab\u043f\u043e\u0432\u043b\u0438\u044f\u043b\u043e \u043d\u0435\u0434\u0430\u0432\u043d\u0435\u0435 \u043d\u0430\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043d\u0430 \u0435\u0435 \u000d\u000a\u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u00bb. \u000d\u000a\u0412 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u043f\u043e\u0436\u0430\u0440\u0430 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043f\u043e\u0441\u0442\u0440\u0430\u0434\u0430\u043b.\u000d\u000a06 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u041e\u043a\u043e\u043b\u043e \u0442\u044b\u0441\u044f\u0447\u0438 \u0441\u0443\u0434\u043e\u0432 \u0437\u0430\u0441\u0442\u0440\u044f\u043b\u0438 \u0432\u0431\u043b\u0438\u0437\u0438 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430\u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u043e\u0440\u0441\u043a\u0438\u0445 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432. \u000d\u000a\u041e\u043d \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 20% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043d\u0435\u0444\u0442\u044c\u044e. \u0418\u0440\u0430\u043d \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b \u043f\u0440\u043e\u043b\u0438\u0432 \u0432 \u043d\u0430\u0447\u0430\u043b\u0435 \u043d\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u044d\u0442\u0430\u043f\u0430 \u0432\u043e\u0439\u043d\u044b \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000d\u000a\u0424\u043e\u043d\u0434\u043e\u0432\u044b\u0435 \u0440\u044b\u043d\u043a\u0438 \u041e\u0410\u042d \u0440\u0435\u0437\u043a\u043e \u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u000d\u000a\u0432 \u0441\u0440\u0435\u0434\u0443 \u043f\u043e\u0441\u043b\u0435 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0442\u043e\u0440\u0433\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0431\u044b\u043b\u0438 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u043d\u0430 \u0434\u0432\u0430 \u0434\u043d\u044f \u0438\u0437-\u0437\u0430 \u043d\u0430\u0447\u0430\u043b\u0430 \u000d\u000a\u0432\u043e\u0439\u043d\u044b \u0441 \u0418\u0440\u0430\u043d\u043e\u043c. \u0418\u043d\u0434\u0435\u043a\u0441 Dubai Financial Market \u000d\u000a(DFM) \u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0438 \u0443\u043f\u0430\u043b \u043d\u0430 4,7%, \u0430 \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u000d\u000a\u0438\u043d\u0434\u0435\u043a\u0441 Abu Dhabi Securities Exchange (ADX) \u000d\u000a\u0441\u043d\u0438\u0437\u0438\u043b\u0441\u044f \u043d\u0430 3,5%, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043d\u0430 \u0440\u044b\u043d\u043e\u043a \u000d\u000a\u043e\u0431\u0440\u0443\u0448\u0438\u043b\u043e\u0441\u044c \u043d\u0430\u043a\u043e\u043f\u0438\u0432\u0448\u0435\u0435\u0441\u044f \u0437\u0430 \u0432\u0440\u0435\u043c\u044f \u043f\u0430\u0443\u0437\u044b \u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u043e\u0432.\u000a\u000d\u000a\u041f\u043e\u0432\u043e\u0434\u043e\u043c \u0434\u043b\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u0440\u044b\u043d\u043a\u043e\u0432 \u0441\u0442\u0430\u043b\u0438 \u0440\u0430\u043a\u0435\u0442\u043d\u044b\u0435 \u000d\u000a\u0443\u0434\u0430\u0440\u044b \u0418\u0440\u0430\u043d\u0430 \u043f\u043e \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u041e\u0410\u042d, \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043f\u043e\u0433\u0438\u0431\u043b\u0438 \u0442\u0440\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0431\u044b\u043b\u0438 \u000d\u000a\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0437\u0430\u043a\u0440\u044b\u0442\u044b \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u044b \u0441\u0442\u0440\u0430\u043d\u044b. \u0410\u0442\u0430\u043a\u0438\u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043b\u0438 \u0437\u0430 \u0441\u0443\u0431\u0431\u043e\u0442\u043d\u0438\u043c\u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f\u043c\u0438, \u043a\u043e\u0433\u0434\u0430 \u000d\u000a\u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u043d\u0430\u0447\u0430\u043b\u0438 \u043d\u0430\u043d\u043e\u0441\u0438\u0442\u044c \u0443\u0434\u0430\u0440\u044b \u000d\u000a\u043f\u043e \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0418\u0440\u0430\u043d\u0430. \u041a\u043e\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u043d\u0430 \u043e\u0431\u0435\u0438\u0445 \u0431\u0438\u0440\u0436\u0430\u0445 \u0443\u043f\u0430\u043b\u0438 \u000d\u000a\u0434\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u043e\u0433\u043e \u0434\u043d\u0435\u0432\u043d\u043e\u0433\u043e \u043b\u0438\u043c\u0438\u0442\u0430 \u000d\u000a\u0432 5% \u0438\u043b\u0438 \u043f\u0440\u0438\u0431\u043b\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u043a \u043d\u0435\u043c\u0443. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432 \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0430\u0441\u044c \u043d\u0438\u0437\u043a\u043e\u0439.\u000a\u000d\u000a\u041d\u0430 \u0444\u043e\u043d\u0434\u043e\u0432\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u0414\u0443\u0431\u0430\u044f \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 5% \u000d\u000a\u043f\u043e\u0434\u0435\u0448\u0435\u0432\u0435\u043b\u0438 \u0430\u043a\u0446\u0438\u0438 Emirates NBD, \u0434\u0435\u0432\u0435\u043b\u043e\u043f\u0435\u0440\u0430 \u000d\u000aEmaar Properties \u0438 \u043b\u043e\u0443\u043a\u043e\u0441\u0442\u0435\u0440\u0430 Air Arabia. \u000d\u000a\u0410\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u043e\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u043b\u0438 \u0431\u0443\u043c\u0430\u0433\u0438 Adnoc \u000d\u000aGas, AD Ports \u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u0441\u0442\u0440\u0430\u043d\u044b First \u000d\u000aAbu Dhabi Bank \u043d\u0430 \u0441\u0442\u043e\u043b\u0438\u0447\u043d\u043e\u0439 \u0431\u0438\u0440\u0436\u0435.\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0412\u0435\u043b\u0438\u043a\u043e\u0431\u0440\u0438\u0442\u0430\u043d\u0438\u044f \u043d\u0430\u043f\u0440\u0430\u0432\u0438\u0442 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0438 \u0434\u043b\u044f \u000d\u000a\u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0443\u0434\u0430\u0440\u043e\u0432 \u043f\u043e \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0443 \u000d\u000a28 \u0444\u0435\u0432\u0440\u0430\u043b\u044f \u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u043d\u0430\u0447\u0430\u043b\u0438 \u0432\u043e\u0439\u043d\u0443 \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430. \u0418\u0441\u043b\u0430\u043c\u0441\u043a\u0430\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430 \u0430\u0442\u0430\u043a\u0443\u0435\u0442 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u0431\u0430\u0437\u044b, \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u043a\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443, \u043f\u043e\u0440\u0442\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u000d\u000a\u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430.\u000d\u000a\u0427\u0435\u0442\u044b\u0440\u0435 \u0431\u0440\u0438\u0442\u0430\u043d\u0441\u043a\u0438\u0445 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f, \u000d\u000a\u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0432 \u041a\u0430\u0442\u0430\u0440, \u0431\u0443\u0434\u0443\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u0434\u043b\u044f \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0443\u0434\u0430\u0440\u043e\u0432 \u043f\u043e \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0443. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u043e\u0444\u0438\u0441 \u043f\u0440\u0435\u043c\u044c\u0435\u0440-\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430 \u000d\u000a\u0412\u0435\u043b\u0438\u043a\u043e\u0431\u0440\u0438\u0442\u0430\u043d\u0438\u0438 \u041a\u0438\u0440\u0430 \u0421\u0442\u0430\u0440\u043c\u0435\u0440\u0430 \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u0435\u0433\u043e \u000d\u000a\u0442\u0435\u043b\u0435\u0444\u043e\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430 \u0441 \u043a\u043e\u0440\u043e\u043b\u0435\u043c \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u0425\u0430\u043c\u0430\u0434\u043e\u043c \u0431\u0435\u043d \u0418\u0441\u043e\u0439 \u0410\u043b\u044c \u0425\u0430\u043b\u0438\u0444\u043e\u0439.\u000d\u000a\u041a\u043e\u0440\u043e\u043b\u044c \u043f\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u043c\u044c\u0435\u0440\u0430, \u000d\u000a\u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c, \u0447\u0442\u043e \u0438\u0445 \u043e\u043f\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u000d\u000a\u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0432 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0435 \u0434\u043d\u0438 \u043d\u0430\u0447\u043d\u0443\u0442 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u000d\u000a\u043f\u043b\u0430\u043d\u0430.\u000d\u000a07 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0411\u0438\u0440\u0436\u0438 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0437\u0430\u043a\u0440\u044b\u043b\u0438\u0441\u044c \u0440\u043e\u0441\u0442\u043e\u043c \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0441\u043b\u043e\u0432 \u0422\u0440\u0430\u043c\u043f\u0430 \u043e \u0434\u0435\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438\u000d\u000a\u0418\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u044b \u043f\u0435\u0440\u0435\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0442 \u0441\u0432\u043e\u0438 \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u0438, \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u044f \u0432 \u043f\u0435\u0440\u0432\u0443\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u0434\u043e\u043b\u044e \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0438\u0445 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043e\u0432, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0440\u0438\u0441\u043a-\u043f\u0440\u0435\u043c\u0438\u044f \u043d\u0430 \u044d\u0442\u043e\u043c \u0440\u044b\u043d\u043a\u0435 \u043e\u0441\u0442\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0438\u0437\u043a\u043e\u0439 \u043f\u043e\u0441\u043b\u0435 \u0441\u0438\u043b\u044c\u043d\u043e\u0433\u043e \u000d\u000a\u0440\u043e\u0441\u0442\u0430 \u0432 \u043d\u0430\u0447\u0430\u043b\u0435 \u0433\u043e\u0434\u0430.\u000d\u000a\u0424\u043e\u043d\u0434\u043e\u0432\u044b\u0435 \u0440\u044b\u043d\u043a\u0438 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u043d\u0430\u0447\u0430\u043b\u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u043c\u0430 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0439 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0421\u0428\u0410 \u000d\u000a\u0414\u043e\u043d\u0430\u043b\u044c\u0434\u0430 \u0422\u0440\u0430\u043c\u043f\u0430 \u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0439 \u0441\u043a\u043e\u0440\u043e\u0439 \u000d\u000a\u0434\u0435\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000a\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u0438\u043d\u0434\u0435\u043a\u0441 \u0444\u043e\u043d\u0434\u043e\u0432\u043e\u0439 \u0431\u0438\u0440\u0436\u0438 \u0414\u0443\u0431\u0430\u044f \u000d\u000a\u0432\u043e \u0432\u0442\u043e\u0440\u043d\u0438\u043a \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 2%.  \u000a\u000d\u000a\u041b\u0438\u0434\u0435\u0440\u043e\u043c \u0440\u043e\u0441\u0442\u0430 \u0441\u0442\u0430\u043b\u0438 \u0430\u043a\u0446\u0438\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u000d\u000a\u044d\u043c\u0438\u0440\u0430\u0442\u0430 Emirates NBD, \u043f\u043e\u0434\u0441\u043a\u043e\u0447\u0438\u0432\u0448\u0438\u0435 \u043d\u0430 8,3%. \u000d\u000a\u0410\u043a\u0446\u0438\u0438 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0431\u0438\u0440\u0436\u0438 Dubai Financial Market \u000d\u000a\u0442\u0430\u043a\u0436\u0435 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043b\u0438 \u2014 \u043d\u0430 8,2%. \u041e\u0434\u043d\u0430\u043a\u043e \u0440\u043e\u0441\u0442 \u0431\u044b\u043b \u000d\u000a\u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0441\u0434\u0435\u0440\u0436\u0430\u043d \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435\u043c \u043a\u043e\u0442\u0438\u0440\u043e\u0432\u043e\u043a \u0440\u044f\u0434\u0430 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439. \u0410\u043a\u0446\u0438\u0438 \u0434\u0435\u0432\u0435\u043b\u043e\u043f\u0435\u0440\u0430 Emaar \u000d\u000aProperties \u0443\u043f\u0430\u043b\u0438 \u043d\u0430 4,1%, \u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u043d\u043e\u0439 \u000d\u000a\u0430\u0432\u0438\u0430\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Air Arabia \u2014 \u043d\u0430 3,2%, \u0447\u0442\u043e \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442 \u000d\u000a\u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0449\u0443\u044e\u0441\u044f \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432.\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0438\u043d\u0434\u0435\u043a\u0441 \u0431\u0438\u0440\u0436\u0438 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u043b \u000d\u000a1,4%. \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0443 \u0440\u044b\u043d\u043a\u0443 \u043e\u043a\u0430\u0437\u0430\u043b\u0438 \u0430\u043a\u0446\u0438\u0438\u000d\u000a\u0431\u0430\u043d\u043a\u043e\u0432\u0441\u043a\u043e\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430. \u0426\u0435\u043d\u043d\u044b\u0435 \u0431\u0443\u043c\u0430\u0433\u0438 Abu Dhabi \u000d\u000aCommercial Bank \u0438 Abu Dhabi Islamic Bank \u000d\u000a\u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 8,7% \u0438 5,8% \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e.\u000a\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0439 \u0438\u043d\u0434\u0435\u043a\u0441 TASI \u043f\u043e\u0434\u043d\u044f\u043b\u0441\u044f \u043d\u0430 0,9%, \u0447\u0435\u043c\u0443 \u000d\u000a\u0441\u043f\u043e\u0441\u043e\u0431\u0441\u0442\u0432\u043e\u0432\u0430\u043b 2-\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u044b\u0439 \u0440\u043e\u0441\u0442 \u0430\u043a\u0446\u0438\u0439 Al Rajhi \u000d\u000aBank. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u0430\u043a\u0446\u0438\u0438 \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0433\u043e \u0433\u0438\u0433\u0430\u043d\u0442\u0430 Saudi \u000d\u000aAramco \u043f\u043e\u0434\u0435\u0448\u0435\u0432\u0435\u043b\u0438 \u043d\u0430 0,8% \u043f\u043e\u0441\u043b\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u043f\u0430\u0434\u0435\u043d\u0438\u0438 \u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u043d\u0430 12% \u0438\u0437-\u0437\u0430 \u043d\u0438\u0437\u043a\u0438\u0445 \u000d\u000a\u0446\u0435\u043d \u043d\u0430 \u043d\u0435\u0444\u0442\u044c.\u000a\u000d\u000a\u041a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0439 \u0444\u043e\u043d\u0434\u043e\u0432\u044b\u0439 \u0438\u043d\u0434\u0435\u043a\u0441 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 2,5%. \u000d\u000a\u0412 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438, \u0430\u043a\u0446\u0438\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000aQatar National Bank \u0438 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0433\u043b\u043e\u043c\u0435\u0440\u0430\u0442\u0430 Industries Qatar \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043b\u0438 \u000d\u000a\u043d\u0430 4,3% \u0438 4,6% \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e.\u000a\u000d\u000a\u0418\u043d\u0434\u0435\u043a\u0441 \u0444\u043e\u043d\u0434\u043e\u0432\u043e\u0439 \u0431\u0438\u0440\u0436\u0438 \u041a\u0443\u0432\u0435\u0439\u0442\u0430 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 1,4%, \u000d\u000a\u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u0440\u044b\u043d\u043a\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0438 \u041e\u043c\u0430\u043d\u0430 \u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u000d\u000a\u043d\u0430 0,4% \u0438 0,2%. \u0417\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0430 \u0435\u0433\u0438\u043f\u0435\u0442\u0441\u043a\u0438\u0439 \u0438\u043d\u0434\u0435\u043a\u0441 EGX30 \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u043b 2,9%.\u000d\u000a08 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0435\u0444\u0442\u0438 \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435\u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0441\u0442\u0430\u043b\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0439 \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u0440\u0435\u0433\u0438\u043e\u043d\u0430, \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0448\u0435\u0439 \u0434\u043e\u0431\u044b\u0447\u0443. \u0420\u0430\u043d\u0435\u0435 \u044d\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u043b\u0438 \u000d\u000a\u041e\u0410\u042d, \u0418\u0440\u0430\u043a, \u041a\u0443\u0432\u0435\u0439\u0442 \u0438 \u041a\u0430\u0442\u0430\u0440 \u2014 \u0438\u0437-\u0437\u0430 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043e\u0442\u0433\u0440\u0443\u0436\u0430\u0442\u044c \u043d\u0435\u0444\u0442\u044c \u043c\u043e\u0440\u0441\u043a\u0438\u043c \u043f\u0443\u0442\u0435\u043c.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043d\u0430\u0447\u0430\u043b\u0430 \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0442\u044c \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u043d\u0435\u0444\u0442\u0438 \u043d\u0430 \u0440\u044f\u0434\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0432\u043e\u0439\u043d\u044b \u000d\u000a\u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u000d\u000a\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0430\u0440\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043b\u0430 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u043e \u000d\u000a\u0432 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u043c \u0437\u0430\u043b\u0438\u0432\u0435. \u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u000d\u000aReuters, \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Saudi \u000d\u000aAramco \u0443\u0436\u0435 \u0441\u043d\u0438\u0437\u0438\u043b\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430 \u0434\u0432\u0443\u0445 \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u044b, \u0430 \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430 \u0431\u044b\u0441\u0442\u0440\u043e \u000d\u000a\u0437\u0430\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f. \u000a\u000d\u000a\u0421\u0438\u0442\u0443\u0430\u0446\u0438\u044f \u043d\u0430 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u0440\u044b\u043d\u043a\u0435 \u000d\u000a\u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0432\u0435\u0434\u0443\u0449\u0438\u0445 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a \u000d\u000a\u043c\u0438\u0440\u0430. \u041c\u0438\u043d\u0438\u0441\u0442\u0440\u044b \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0441\u0442\u0440\u0430\u043d G7 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0432\u044b\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043d\u0435\u0444\u0442\u0438 \u000d\u000a\u0438\u0437 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0440\u0435\u0437\u0435\u0440\u0432\u043e\u0432, \u0447\u0442\u043e\u0431\u044b \u000d\u000a\u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u044b\u043d\u043e\u043a.  \u000a\u000d\u000a\u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0435 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u000d\u000a\u0440\u0430\u043d\u0435\u0435 \u043f\u0440\u0438\u0437\u0432\u0430\u043b\u043e \u0432\u044b\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c \u0431\u043e\u043b\u0435\u0435 \u000d\u000a1,2 \u043c\u043b\u0440\u0434 \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0438\u0437 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u0438 \u043e\u043a\u043e\u043b\u043e 600 \u043c\u043b\u043d \u000d\u000a\u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0438\u0437 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439.\u000d\u000a\u0421\u0435\u0440\u044c\u0435\u0437\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0443 \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u0418\u0440\u0430\u043a \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u044e\u0436\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 70% \u2014 \u000d\u000a\u0434\u043e 1,3 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438. \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u000d\u000aBapco \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u043f\u043e\u0441\u043b\u0435 \u0430\u0442\u0430\u043a\u0438 \u000d\u000a\u043d\u0430 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u0421\u0438\u0442\u0440\u0430. \u000d\u000a\u041a\u0443\u0432\u0435\u0439\u0442\u0441\u043a\u0430\u044f \u043d\u0435\u0444\u0442\u044f\u043d\u0430\u044f \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u044f KPC \u000d\u000a\u043f\u0440\u0438\u043d\u044f\u043b\u0430 \u0430\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u000a\u000d\u000a\u0414\u0432\u0438\u0436\u0435\u043d\u0438\u0435 \u0441\u0443\u0434\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u0438\u0439 \u0437\u0430\u043b\u0438\u0432 \u000d\u000a\u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u0430\u043c\u0435\u0440\u043b\u043e. \u0421\u043e\u0442\u043d\u0438 \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u000d\u000a\u0442\u0430\u043d\u043a\u0435\u0440\u043e\u0432 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0443 \u0432\u0445\u043e\u0434\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432, \u0447\u0442\u043e \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0442\u044c \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0440\u044b\u043d\u043a\u0430\u0445. \u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0430\u043c \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u043e\u0432, \u0437\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u000d\u000a10 \u0434\u043d\u0435\u0439 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435\u0444\u0442\u0438 \u0443\u0436\u0435 \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u043e\u0441\u044c \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 200 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u000d\u000a\u0438\u0437-\u0437\u0430 \u043f\u0435\u0440\u0435\u0431\u043e\u0435\u0432 \u0432 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u0445.\u000d\u000a09 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f ADNOC \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0430\u0442\u0430\u043a\u0438 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0430\u000d\u000a\u041c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438, \u0418\u0440\u0430\u043a\u0435, \u041e\u0410\u042d, \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435, \u041a\u0443\u0432\u0435\u0439\u0442\u0435 \u0438 \u041a\u0430\u0442\u0430\u0440\u0435 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0438\u0441\u044c \u043d\u0430 1,9 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438. \u000d\u000a\u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0435\u0444\u0442\u044f\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u000d\u000a(Abu Dhabi National Oil Company, ADNOC) \u000d\u000a\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u000d\u000a\u0420\u0443\u0432\u0435\u0439\u0441 \u0438\u0437-\u0437\u0430 \u043f\u043e\u0436\u0430\u0440\u0430, \u0432\u043e\u0437\u043d\u0438\u043a\u0448\u0435\u0433\u043e \u043f\u043e\u0441\u043b\u0435 \u0430\u0442\u0430\u043a\u0438 \u000d\u000a\u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e Reuters. \u000a\u000d\u000a\u041f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u0431\u044b\u043b \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u000d\u000a\u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043c\u0435\u0440\u044b \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e\u0441\u0442\u0438. \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u043e\u0431\u044a\u0435\u043a\u0442\u044b \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0432 \u0448\u0442\u0430\u0442\u043d\u043e\u043c \u000d\u000a\u0440\u0435\u0436\u0438\u043c\u0435.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u0420\u0443\u0432\u0435\u0439\u0441 \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u0430\u043a\u0442\u0438\u0432 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438. \u000d\u000a\u0415\u0433\u043e \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e \u000d\u000a922 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u043d\u0435\u0444\u0442\u0438 \u0432 \u0441\u0443\u0442\u043a\u0438. \u041d\u0430 \u0435\u0433\u043e \u000d\u000a\u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u044b \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u000d\u000a\u0445\u0438\u043c\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f, \u0437\u0430\u0432\u043e\u0434\u044b \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u000d\u000a\u0443\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0439 \u0438 \u0433\u0430\u0437\u043e\u0432.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0424\u043e\u043d\u0434 Ninety One \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0439 \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u041d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u043d\u0430\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0432\u043c\u0435\u0441\u0442\u0435 \u0432\u044b\u043f\u0443\u0441\u043a\u0430\u044e\u0442 \u0431\u043e\u043b\u0435\u0435 7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0433\u043e\u0434. \u042d\u0442\u043e \u043e\u043a\u043e\u043b\u043e 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430.\u000d\u000a\u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u0430\u044f \u0438\u043d\u0432\u0435\u0441\u0442\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Ninety One \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430 \u0434\u043e\u043b\u044e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0441\u0432\u043e\u0435\u043c \u0444\u043e\u043d\u0434\u0435 \u000d\u000aNinety One Global Natural Resources Fund \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430, \u0432\u044b\u0437\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0435\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u000a\u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e \u0444\u043e\u043d\u0434\u043e\u043c \u0414\u0436\u043e\u0440\u0434\u0436\u0430 \u000d\u000a\u0427\u0435\u0432\u0435\u043b\u0438, \u0440\u044b\u043d\u043e\u043a \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438 \u0431\u0435\u0437 \u0442\u043e\u0433\u043e \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u000d\u000a\u0432 \u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u043d\u043e\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0438, \u0430 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430\u044f \u000d\u000a\u043f\u043e\u0442\u0435\u0440\u044f \u0447\u0430\u0441\u0442\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043c\u043e\u0436\u0435\u0442 \u0443\u0441\u0443\u0433\u0443\u0431\u0438\u0442\u044c \u000d\u000a\u0434\u0435\u0444\u0438\u0446\u0438\u0442. \u00ab\u041c\u044b \u0443\u0436\u0435 \u0438\u043c\u0435\u043b\u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u043d\u0443\u044e \u0434\u043e\u043b\u044e \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u0435 \u043d\u0435\u0434\u0435\u043b\u044e \u043d\u0430\u0437\u0430\u0434, \u000d\u000a\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0438 \u0435\u0435\u00bb, \u2014 \u000d\u000a\u0441\u043a\u0430\u0437\u0430\u043b \u043e\u043d \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0443 Reuters.\u000a\u000d\u000a\u0424\u043e\u043d\u0434 \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u043b \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439, \u000d\u000a\u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0431\u043b\u0438\u0436\u043d\u0435\u0432\u043e\u0441\u0442\u043e\u0447\u043d\u044b\u0439 \u043a\u0440\u0438\u0437\u0438\u0441 \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442, \u0432 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u0432 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0443\u044e \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044e China Hongqiao Group. \u0421\u0440\u0435\u0434\u0438 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0444\u043e\u043d\u0434\u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u044f Rio Tinto, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u043b\u0430 \u043e\u043a\u043e\u043b\u043e \u000d\u000a3,4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f.\u000d\u000a10 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000aMaaden \u0443\u0434\u0432\u043e\u0438\u043b\u0430 \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u0432 2025 \u0433\u043e\u0434\u0443 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u000d\u000a\u0440\u043e\u0441\u0442\u0443 \u0446\u0435\u043d \u043d\u0430 \u0441\u044b\u0440\u044c\u0435\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0442\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u0430\u043c\u0431\u0438\u0446\u0438\u043e\u0437\u043d\u044b\u0445 \u043c\u0435\u0433\u0430\u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0432 \u043f\u043e\u043b\u044c\u0437\u0443 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u043e\u0441\u0442\u0430 \u0437\u0430\u0442\u0440\u0430\u0442 \u0438 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u043e\u0442 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043d\u0435\u0444\u0442\u0438.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000aMaaden \u0443\u0434\u0432\u043e\u0438\u043b\u0430 \u0447\u0438\u0441\u0442\u0443\u044e \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0440\u043e\u0441\u0442\u0443 \u0446\u0435\u043d \u043d\u0430 \u0441\u044b\u0440\u044c\u0435 \u000d\u000a\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u043c \u043e\u0442\u0447\u0435\u0442\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438. \u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 Maaden \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 19% \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 \u000d\u000a39 \u043c\u043b\u0440\u0434 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0445 \u0440\u0438\u0430\u043b\u043e\u0432 ($10,4 \u043c\u043b\u0440\u0434). \u0422\u0430\u043a\u043e\u0439 \u000d\u000a\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u0438 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u0438 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f, \u000d\u000a\u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u0446\u0435\u043d \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0432\u0438\u0434\u044b \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u0435\u0440\u0432\u043e\u0435 \u043f\u043e\u043b\u043d\u043e\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0432 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f Aluminium Bahrain.\u000a\u000d\u000a\u0420\u043e\u0441\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0435\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043b\u0438 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0446\u0435\u043d \u000d\u000a\u043d\u0430 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u0438 \u0441\u044b\u0440\u044c\u0435\u0432\u044b\u0435 \u0442\u043e\u0432\u0430\u0440\u044b. \u000d\u000a\u0421\u0440\u0435\u0434\u043d\u044f\u044f \u0446\u0435\u043d\u0430 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0434\u043b\u044f \u0437\u043e\u043b\u043e\u0442\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u000d\u000a\u043d\u0430 46%, \u0434\u043e 3511 \u0440\u0438\u0430\u043b\u043e\u0432 \u0437\u0430 \u0443\u043d\u0446\u0438\u044e. \u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 8%, \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u0446\u0435\u043d\u0430 \u000d\u000a\u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430 \u0443\u043f\u0430\u043b\u0430 \u043d\u0430 13%. \u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0443\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0439 \u000d\u000a\u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u0434\u0438\u0430\u043c\u043c\u043e\u043d\u0438\u0439\u0444\u043e\u0441\u0444\u0430\u0442\u0430 \u043f\u043e\u0434\u043d\u044f\u043b\u0430\u0441\u044c \u043d\u0430 19%, \u000d\u000a\u0430 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u0430\u043c\u043c\u0438\u0430\u043a\u0430 \u2014 \u0441\u043d\u0438\u0437\u0438\u043b\u0430\u0441\u044c \u043d\u0430 5%. \u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0442\u0430\u043a\u0436\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430, \u0447\u0442\u043e \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u000d\u000a\u043a\u0430\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0440\u0430\u0441\u0445\u043e\u0434\u044b \u043d\u0430 2026 \u0433\u043e\u0434 \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u000d\u000a15,5 \u043c\u043b\u0440\u0434 \u0440\u0438\u0430\u043b\u043e\u0432, \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 12,6 \u043c\u043b\u0440\u0434 \u0440\u0438\u0430\u043b\u043e\u0432 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u044f\u0442 \u043d\u0430 \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u0440\u043e\u0441\u0442\u0430. \u0412 \u0438\u0445 \u0447\u0438\u0441\u043b\u0435 \u000d\u000a\u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u0435 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a \u043f\u0435\u0440\u0432\u043e\u0439 \u0444\u0430\u0437\u044b \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000aPhosphate 3, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0435 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 Al Rjum \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u041c\u0435\u043a\u043a\u0430.\u000d\u000a#\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e #\u0441\u043e\u0431\u044b\u0442\u0438\u0435\u000d\u000a\u0418\u0434 \u0430\u043b\u044c-\u0424\u0438\u0442\u0440 \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 \u043d\u0430\u0447\u0430\u043b\u0441\u044f \u0432\u0435\u0447\u0435\u0440\u043e\u043c 19 \u043c\u0430\u0440\u0442\u0430\u000d\u000a\u0418\u0434 \u0430\u043b\u044c-\u0424\u0438\u0442\u0440, \u0437\u043d\u0430\u043c\u0435\u043d\u0443\u044e\u0449\u0438\u0439 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u0435 \u0441\u0432\u044f\u0449\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0435\u0441\u044f\u0446\u0430 \u0420\u0430\u043c\u0430\u0434\u0430\u043d, \u043d\u0430\u0447\u0430\u043b\u0441\u044f \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 \u0432\u0435\u0447\u0435\u0440\u043e\u043c \u2028\u000d\u000a19 \u043c\u0430\u0440\u0442\u0430 \u0438 \u043f\u0440\u043e\u0434\u043b\u0438\u0442\u0441\u044f \u0434\u043e \u0432\u0435\u0447\u0435\u0440\u0430 20 \u043c\u0430\u0440\u0442\u0430. \u041f\u0440\u0430\u0437\u0434\u043d\u0438\u043a \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0432 \u043f\u0435\u0440\u0432\u044b\u0439 \u0434\u0435\u043d\u044c \u043c\u0435\u0441\u044f\u0446\u0430 \u0428\u0430\u0432\u0432\u0430\u043b\u044c \u000d\u000a\u043f\u043e \u0438\u0441\u043b\u0430\u043c\u0441\u043a\u043e\u043c\u0443 \u043b\u0443\u043d\u043d\u043e\u043c\u0443 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u044e \u0438 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u0434\u0432\u0443\u0445 \u0433\u043b\u0430\u0432\u043d\u044b\u0445 \u0440\u0435\u043b\u0438\u0433\u0438\u043e\u0437\u043d\u044b\u0445 \u0441\u043e\u0431\u044b\u0442\u0438\u0439 \u000d\u000a\u0432 \u0438\u0441\u043b\u0430\u043c\u0435 \u043d\u0430\u0440\u044f\u0434\u0443 \u0441 \u0418\u0434 \u0430\u043b\u044c \u0410\u0434\u0445\u0430. \u000a\u000d\u000a\u0412 \u0431\u043b\u0438\u0436\u043d\u0435\u0432\u043e\u0441\u0442\u043e\u0447\u043d\u044b\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u0418\u0434 \u0430\u043b\u044c-\u0424\u0438\u0442\u0440 \u2014 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a, \u043d\u0430 \u0432\u0440\u0435\u043c\u044f \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043d\u0435\u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u0434\u043d\u0438. \u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0432\u044b\u0445\u043e\u0434\u043d\u044b\u0445 \u043c\u043e\u0436\u0435\u0442 \u0432\u0430\u0440\u044c\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f, \u043e\u0431\u044b\u0447\u043d\u043e \u000d\u000a\u043e\u043d\u0430 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u0442 \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u043e \u0442\u0440\u0435\u0445 \u0434\u043d\u0435\u0439, \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432. \u000a\u000d\u000a\u0412 \u044d\u0442\u0438 \u0434\u043d\u0438 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u043f\u043e\u0441\u0435\u0449\u0430\u044e\u0442 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u044b\u0435 \u043c\u043e\u043b\u0438\u0442\u0432\u044b, \u043f\u0440\u043e\u0432\u043e\u0434\u044f\u0442 \u0432\u0440\u0435\u043c\u044f \u0432 \u043a\u0440\u0443\u0433\u0443 \u0441\u0435\u043c\u044c\u0438 \u0438 \u0434\u0440\u0443\u0437\u0435\u0439, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043f\u043e\u0434\u0430\u0440\u043a\u0430\u043c\u0438 \u0438 \u0443\u0434\u0435\u043b\u044f\u044e\u0442 \u043e\u0441\u043e\u0431\u043e\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u0431\u043b\u0430\u0433\u043e\u0442\u0432\u043e\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\u000d\u000a11 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aSinomine Resource Group \u0432\u0435\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u000d\u000a\u0441 \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u043e \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043b\u0438\u0442\u0438\u044f\u000d\u000a\u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0438\u0439\u0441\u043a\u0438\u0435 \u0432\u043b\u0430\u0441\u0442\u0438 \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u043b\u0438 \u0432\u044b\u0432\u043e\u0437 \u043b\u0438\u0442\u0438\u0435\u0432\u043e\u0433\u043e \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430 \u043d\u0430 \u0433\u043e\u0434 \u0440\u0430\u043d\u044c\u0448\u0435 \u043e\u0431\u0435\u0449\u0430\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u0441\u0440\u043e\u043a\u0430.\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a Sinomine Resource \u000d\u000aGroup \u0434\u043e\u0431\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0439 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043d\u0430 \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0439 \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442. \u0412 \u043a\u043e\u043d\u0446\u0435 \u0444\u0435\u0432\u0440\u0430\u043b\u044f \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u000d\u000a\u0432\u0432\u0435\u043b\u043e \u0437\u0430\u043f\u0440\u0435\u0442 \u043d\u0430 \u0435\u0433\u043e \u0432\u044b\u0432\u043e\u0437 \u2014 \u0445\u043e\u0442\u044f \u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u043e\u0431\u0435\u0449\u0430\u043b\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u044d\u0442\u043e \u043b\u0438\u0448\u044c \u0432 2027 \u0433\u043e\u0434\u0443. \u041f\u0440\u0430\u0432\u043e \u000d\u000a\u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0442\u0435\u043f\u0435\u0440\u044c \u043f\u043e\u043b\u0443\u0447\u0430\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0441 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u043c\u0438 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f\u043c\u0438 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u043c\u0438 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044f\u043c\u0438.\u000d\u000aSinomine \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442, \u0447\u0442\u043e \u0435\u0435 \u00ab\u0434\u043e\u0447\u043a\u0430\u00bb Bikita \u000d\u000a\u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u044d\u0442\u0438\u043c \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f\u043c \u0438 \u043d\u043e\u0432\u044b\u0435 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043d\u0430 \u043d\u0435\u0435 \u043d\u0435 \u043f\u043e\u0432\u043b\u0438\u044f\u044e\u0442. \u0417\u0430\u0432\u043e\u0434\u044b \u000d\u000a\u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0441\u0443\u043b\u044c\u0444\u0430\u0442\u0430 \u043b\u0438\u0442\u0438\u044f \u0432 \u0441\u0442\u0440\u0430\u043d\u0435 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0441\u0442\u0440\u043e\u044f\u0442 Sichuan Yahua Industrial Group \u0438 Zhejiang \u000d\u000aHuayou Cobalt (\u043f\u0440\u043e\u0435\u043a\u0442 Prospect Lithium \u000d\u000aZimbabwe) \u2014 \u0438\u0445 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044f \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u000d\u000a\u043d\u0430 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0420\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u043e\u0434\u043e\u0431\u0440\u0438\u043b \u043f\u043e\u043a\u0443\u043f\u043a\u0443 Chinalco \u0438 Rio Tinto \u000d\u000a\u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f CBA\u000d\u000a\u0421\u0443\u043c\u043c\u0430 \u0441\u0434\u0435\u043b\u043a\u0438 \u2014 \u0441\u0432\u044b\u0448\u0435 $900 \u043c\u043b\u043d.\u000d\u000a\u0411\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0438\u0435 \u0432\u043b\u0430\u0441\u0442\u0438 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u0435 \u000d\u000a\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u0430\u043a\u0435\u0442\u0430 \u0430\u043a\u0446\u0438\u0439 Companhia \u000d\u000aBrasileira de Aluminio (CBA) \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 Chinalco \u000d\u000a\u0438 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u043e \u0431\u0440\u0438\u0442\u0430\u043d\u0441\u043a\u043e\u0439 Rio Tinto. \u042d\u0442\u043e \u000d\u000a\u0441\u043d\u044f\u043b\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u0435 \u000d\u000a\u0434\u043b\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u0441\u0434\u0435\u043b\u043a\u0438, \u0430\u043d\u043e\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u000d\u000a\u0432 \u044f\u043d\u0432\u0430\u0440\u0435: \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0432\u044b\u043a\u0443\u043f\u0430\u044e\u0442 \u0443 Grupo \u000d\u000aVotorantim 68,6% \u0430\u043a\u0446\u0438\u0439 CBA \u0437\u0430 4,69 \u043c\u043b\u0440\u0434 \u000d\u000a\u0440\u0435\u0430\u043b\u043e\u0432 (~$910 \u043c\u043b\u043d).\u000d\u000a\u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u043c \u043f\u0430\u043a\u0435\u0442\u043e\u043c \u043f\u0435\u0440\u0435\u0439\u0434\u0435\u0442 \u043a \u0421\u041f, \u000d\u000a\u0433\u0434\u0435 Chinalco \u043f\u043e\u043b\u0443\u0447\u0438\u0442 67%, \u0430 Rio Tinto \u2014 33%. \u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0443\u0436\u0435 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u000d\u000a14,55% Rio Tinto. \u0412 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 15 \u0434\u043d\u0435\u0439 \u043d\u043e\u0432\u044b\u0435 \u000d\u000a\u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u044b \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043c\u0438\u043d\u043e\u0440\u0438\u0442\u0430\u0440\u043d\u044b\u043c \u000d\u000a\u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u0430\u043c \u043e\u0444\u0435\u0440\u0442\u0443 \u2014 \u0435\u0449\u0435 \u043d\u0430 2,1 \u043c\u043b\u0440\u0434 \u0440\u0435\u0430\u043b\u043e\u0432 \u000d\u000a($400 \u043c\u043b\u043d). \u0420\u0430\u043d\u0435\u0435 \u0438\u043d\u0442\u0435\u0440\u0435\u0441 \u043a CBA \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u043b\u0430 \u000d\u000aEmirates Global Aluminium \u0438\u0437 \u041e\u0410\u042d, \u043e\u0434\u043d\u0430\u043a\u043e \u000d\u000a\u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043d\u0435 \u0431\u044b\u043b\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u044b.\u000d\u000a12 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041e\u043a\u043e\u043b\u043e \u0442\u0440\u0435\u0442\u0438 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 HPAL-\u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u043e\u0432 \u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0443\u000d\u000a\u0422\u0440\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u044f\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043d\u0435\u0434\u0435\u043b\u044c, \u0435\u0449\u0435 \u043e\u0434\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e\u0438\u0442 \u000d\u000a\u0434\u043e \u0442\u0440\u0435\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432.\u000d\u000a\u0427\u0435\u0442\u044b\u0440\u0435 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u0430 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u043c\u0435\u0442\u043e\u0434\u043e\u043c \u043a\u0438\u0441\u043b\u043e\u0442\u043d\u043e\u0433\u043e \u0432\u044b\u0449\u0435\u043b\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u044f \u043f\u043e\u0434 \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u0438\u043c \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c (HPAL) \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 GEM \u000d\u000a\u0432 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u043f\u0430\u0440\u043a\u0435 Morowali \u000d\u000a\u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0443 \u043f\u043e\u0441\u043b\u0435 \u043e\u0431\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u0434\u0430\u043c\u0431\u044b \u0445\u0432\u043e\u0441\u0442\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430, \u0443\u043d\u0435\u0441\u0448\u0435\u0433\u043e \u0436\u0438\u0437\u043d\u044c \u000d\u000a\u043e\u0434\u043d\u043e\u0433\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430. \u041d\u0430 \u044d\u0442\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u043a\u043e\u043b\u043e 30% \u0432\u0441\u0435\u0445 HPAL-\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438.\u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0430\u044f \u0438\u0437 \u043f\u0440\u043e\u0441\u0442\u0430\u0438\u0432\u0430\u044e\u0449\u0438\u0445 \u2014 QMB New \u000d\u000aEnergy Materials \u2014 \u043c\u043e\u0436\u0435\u0442 \u043d\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0434\u043e \u0442\u0440\u0435\u0445 \u000d\u000a\u043c\u0435\u0441\u044f\u0446\u0435\u0432. GEM \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0435\u0433\u043e \u0441\u0430\u043c\u044b\u043c \u000d\u000a\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u043c; \u0441\u0440\u0435\u0434\u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u000d\u000a\u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u0421\u041f \u2014 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 Tsingshan (10%) \u000d\u000a\u0438 Brunp (\u0434\u043e\u0447\u0435\u0440\u043d\u044f\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 CATL, 10%), \u000d\u000a\u044e\u0436\u043d\u043e\u043a\u043e\u0440\u0435\u0439\u0441\u043a\u0430\u044f Ecopro (9%) \u0438 \u044f\u043f\u043e\u043d\u0441\u043a\u0430\u044f Hanwa \u000d\u000a(8%).\u000a\u000d\u000a\u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0442\u0440\u0438 \u0421\u041f \u0441 \u0443\u0447\u0430\u0441\u0442\u0438\u0435\u043c GEM \u2014 Green Eco \u000d\u000aNickel, Meiming New Energy Material \u0438 ESG New \u000d\u000aEnergy Material (\u043f\u0430\u0440\u0442\u043d\u0435\u0440 \u0432\u0441\u0435\u0445 \u0442\u0440\u0435\u0445 \u2014 \u000d\u000a\u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u0430\u044f Merdeka Battery Materials) \u2014 \u000d\u000a\u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u0438, \u043f\u043e \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f\u043c, \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u044f\u0442 \u000d\u000a\u0440\u0430\u0431\u043e\u0442\u0443 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043d\u0435\u0434\u0435\u043b\u044c.\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f\u000d\u000a\u0442\u0435\u0445\u043d\u043e\u043f\u0430\u0440\u043a\u000d\u000aMor\u043ewali\u000d\u000a13 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0443\u044e CMOC \u043e\u0431\u0432\u0438\u043d\u0438\u043b\u0438 \u0432 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f\u0445 \u043d\u0430 \u0440\u0443\u0434\u043d\u0438\u043a\u0435 \u0432 \u0414\u0420\u041a\u000d\u000a\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u041d\u041a\u041e \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u043f\u0440\u0435\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u0434\u0438\u043e\u043a\u0441\u0438\u0434\u0430 \u0441\u0435\u0440\u044b \u0432 \u0432\u043e\u0437\u0434\u0443\u0445\u0435.\u000d\u000aEnvironmental Investigation Agency (EIA) \u000d\u000a\u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u0442\u0440\u0435\u0445\u043b\u0435\u0442\u043d\u0435\u0433\u043e \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u043e\u0431\u0432\u0438\u043d\u0438\u043b\u0430 China Molybdenum (CMOC Group) \u000d\u000a\u0432 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f\u0445 \u043d\u0430 \u0440\u0443\u0434\u043d\u0438\u043a\u0435 \u000d\u000a\u0422\u0435\u043d\u043a\u0435-\u0424\u0443\u043d\u0433\u0443\u0440\u0443\u043c\u0435 \u2014 \u043e\u0434\u043d\u043e\u043c \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u000d\u000a\u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043c\u0438\u0440\u0430, \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 \u0432 \u0414\u0420\u041a \u0432 2016 \u0433\u043e\u0434\u0443. \u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u041d\u041a\u041e, \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u0430 \u0436\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043b\u0435\u0433\u0430\u044e\u0449\u0438\u0445 \u0440\u0430\u0439\u043e\u043d\u043e\u0432 \u000d\u000a\u0441\u0442\u0430\u043b\u0438 \u043c\u0430\u0441\u0441\u043e\u0432\u043e \u043e\u0431\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u043a \u0432\u0440\u0430\u0447\u0430\u043c \u0441 \u043a\u0430\u0448\u043b\u0435\u043c \u000d\u000a\u0441 \u043a\u0440\u043e\u0432\u044c\u044e, \u043f\u043d\u0435\u0432\u043c\u043e\u043d\u0438\u0435\u0439 \u0438 \u0431\u0440\u043e\u043d\u0445\u0438\u0442\u043e\u043c. \u000d\u000a\u041c\u043e\u043d\u0438\u0442\u043e\u0440\u0438\u043d\u0433 \u0432\u043e\u0437\u0434\u0443\u0445\u0430 \u0432\u044b\u044f\u0432\u0438\u043b \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u000d\u000a\u043f\u0440\u0435\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0445 \u043d\u043e\u0440\u043c \u000d\u000a\u043f\u043e \u0434\u0438\u043e\u043a\u0441\u0438\u0434\u0443 \u0441\u0435\u0440\u044b \u2014 \u0433\u0430\u0437\u0443, \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u043c\u043e\u043c\u0443 \u000d\u000a\u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u0439 \u0440\u0443\u0434\u044b.\u000a\u000d\u000aEIA \u043f\u043e\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043b\u0430 \u043e\u0442 CMOC \u0432\u044b\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u000d\u000a\u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430\u043c \u0438 \u043c\u0435\u0441\u0442\u043d\u044b\u043c \u0436\u0438\u0442\u0435\u043b\u044f\u043c \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u0438, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0440\u0430\u0431\u043e\u0442\u0443 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u0434\u043e \u0443\u0441\u0442\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043e\u0431\u0432\u0438\u043d\u0435\u043d\u0438\u044f \u043e\u0442\u0432\u0435\u0440\u0433\u043b\u0430, \u0437\u0430\u044f\u0432\u0438\u0432 \u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u000d\u000a\u0432\u044b\u0431\u0440\u043e\u0441\u043e\u0432 \u0437\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u0414\u0420\u041a \u000d\u000a\u0438 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u043c \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0430\u043c.\u000d\u000a\u0421\u0440\u0435\u0434\u0438 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 \u0433\u0438\u0434\u0440\u043e\u043a\u0441\u0438\u0434\u0430 \u000d\u000a\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0441 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u2014 BMW, Mercedes-Benz, \u000d\u000aStellantis \u0438 Volkswagen; \u0447\u0430\u0441\u0442\u044c \u0438\u0437 \u043d\u0438\u0445 \u0443\u0436\u0435 \u000d\u000a\u0437\u0430\u043f\u0440\u043e\u0441\u0438\u043b\u0430 \u0443 CMOC \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438\u0437 \u0434\u043e\u043a\u043b\u0430\u0434\u0430. \u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u0422\u0435\u043d\u043a\u0435-\u0424\u0443\u043d\u0433\u0443\u0440\u0443\u043c\u0435, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0432 \u0414\u0420\u041a \u0440\u0443\u0434\u043d\u0438\u043a \u041a\u0438\u0441\u0430\u043d\u0444\u0443. CMOC \u000d\u000a\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432 \u043c\u0438\u0440\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u043c \u000d\u000a\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430, \u0432 2023 \u0433\u043e\u0434\u0443 \u043e\u0431\u043e\u0433\u043d\u0430\u0432\u0448\u0438\u043c Glencore.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u043b\u043e\u0436\u0438\u0442\u044c \u0432\u0438\u0437\u0438\u0442 \u0432 \u041a\u0438\u0442\u0430\u0439 \u043d\u0430 \u043c\u0435\u0441\u044f\u0446\u000d\u000a\u041f\u043b\u0430\u043d\u044b \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c \u0438\u0437-\u0437\u0430 \u0432\u043e\u0439\u043d\u044b \u0432 \u0418\u0440\u0430\u043d\u0435.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0421\u0428\u0410 \u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435 \u0432\u0438\u0437\u0438\u0442\u0430 \u0432 \u041a\u041d\u0420, \u000d\u000a\u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u043d\u0430 \u043a\u043e\u043d\u0435\u0446 \u043c\u0430\u0440\u0442\u0430 \u2014 \u043d\u0430\u0447\u0430\u043b\u043e \u000d\u000a\u0430\u043f\u0440\u0435\u043b\u044f. \u041f\u0440\u0438\u0447\u0438\u043d\u043e\u0439 \u0441\u0442\u0430\u043b\u0430 \u0432\u043e\u0439\u043d\u0430 \u0432 \u0418\u0440\u0430\u043d\u0435: \u000d\u000a\u043f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0422\u0440\u0430\u043c\u043f\u0430, \u0432 \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u0439 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438 \u000d\u000a\u043e\u043d \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u043c \u043e\u0441\u0442\u0430\u0432\u0430\u0442\u044c\u0441\u044f \u0432 \u0441\u0442\u0440\u0430\u043d\u0435.\u000d\u000a\u0421\u0442\u043e\u0440\u043e\u043d\u044b \u0443\u0436\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u044e\u0442 \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0441\u0440\u043e\u043a\u043e\u0432 \u000d\u000a\u043f\u043e\u0435\u0437\u0434\u043a\u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u043c\u0435\u0441\u044f\u0446. \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u0430\u044f \u0432\u0441\u0442\u0440\u0435\u0447\u0430 \u000d\u000a\u0434\u043e\u043b\u0436\u043d\u0430 \u0441\u0442\u0430\u0442\u044c \u043f\u0435\u0440\u0432\u044b\u043c \u0432\u0438\u0437\u0438\u0442\u043e\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0421\u0428\u0410 \u0432 \u041a\u0438\u0442\u0430\u0439 \u0441 2017 \u0433\u043e\u0434\u0430.\u000d\u000a14 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f\u000d\u000a\u0421\u0428\u0410 \u043d\u0430\u0447\u0430\u043b\u0438 \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0442\u0438\u0432 \u041a\u0438\u0442\u0430\u044f \u0438\u0437-\u0437\u0430 \u000d\u000a\u0438\u0437\u0431\u044b\u0442\u043e\u0447\u043d\u044b\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439\u000d\u000a\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0438\u0445 \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043d\u044b\u043c \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e\u043c \u041a\u041d\u0420.\u000d\u000a\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0421\u0428\u0410 \u0438\u043d\u0438\u0446\u0438\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u000d\u000a\u0432 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0438 \u041a\u0438\u0442\u0430\u044f \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u000d\u000a\u043d\u0430 \u043f\u0440\u0435\u0434\u043c\u0435\u0442 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0439 \u000d\u000a\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438. \u041f\u043e\u0432\u043e\u0434\u043e\u043c \u0441\u0442\u0430\u043b\u0438 \u0438\u0437\u0431\u044b\u0442\u043e\u0447\u043d\u044b\u0435 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u0432 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435, \u043f\u043e \u043c\u043d\u0435\u043d\u0438\u044e \u000d\u000a\u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0430, \u0432\u044b\u0442\u0435\u0441\u043d\u044f\u044e\u0442 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0438 \u0441\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438.\u000d\u000a\u0420\u0430\u0437\u0431\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043f\u043e \u0440\u0430\u0437\u0434\u0435\u043b\u0443 \u000d\u000a301 \u0417\u0430\u043a\u043e\u043d\u0430 \u043e \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 1974 \u0433\u043e\u0434\u0430, \u043d\u0430\u0434\u0435\u043b\u044f\u044e\u0449\u0435\u043c\u0443 \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f\u043c\u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0442\u044c \u043c\u0435\u0440\u044b \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0431\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0442\u0440\u0430\u043d. \u000d\u000a\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u0421\u0428\u0410 \u043d\u0430 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u0430\u0445 \u000d\u000a\u0414\u0436\u0435\u0439\u043c\u0438\u0441\u043e\u043d \u0413\u0440\u0438\u0440 \u0443\u043a\u0430\u0437\u0430\u043b, \u0447\u0442\u043e \u043c\u043d\u043e\u0433\u0438\u0435 \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u044b \u000d\u000a\u00ab\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 \u0442\u043e\u0432\u0430\u0440\u043e\u0432, \u0447\u0435\u043c \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u044c \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0440\u0430\u043d\u044b\u00bb, \u0430 \u044d\u0442\u043e \u043f\u043e\u0434\u0430\u0432\u043b\u044f\u0435\u0442 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u0438\u0432\u0435\u0441\u0442\u0438 \u000d\u000a\u043a \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438\u000d\u000a\u041e\u043a\u043e\u043b\u043e 75% \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0439 \u0434\u043b\u044f \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0441\u0435\u0440\u044b \u043f\u043e\u0441\u0442\u0443\u043f\u0430\u043b\u043e \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044e \u0438\u0437 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0430.\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u0432\u044b\u043f\u0443\u0441\u043a \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0438\u0437 \u0437\u0430 \u0432\u043e\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430. \u000d\u000a\u0411\u043e\u043b\u0435\u0435 75% \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0438\u043c\u043f\u043e\u0440\u0442\u0430 \u0441\u0435\u0440\u044b \u000d\u000a\u043f\u043e\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u000d\u000a\u0430 \u0442\u0430\u043a\u0438\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u043e\u0441\u043b\u043e\u0436\u043d\u0435\u043d\u044b \u000d\u000a\u0432\u043e\u0435\u043d\u043d\u044b\u043c\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f\u043c\u0438 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435.\u000a\u000d\u000a\u0421\u0435\u0440\u0430 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0441\u0435\u0440\u043d\u043e\u0439 \u000d\u000a\u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u043a\u043e\u0442\u043e\u0440\u0430\u044f, \u0432 \u0441\u0432\u043e\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c, \u000d\u000a\u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u0432\u044b\u0449\u0435\u043b\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u000d\u000a\u0438\u0437 \u0440\u0443\u0434\u044b \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0438\u043a\u0435\u043b\u044f \u0438 \u043c\u0435\u0434\u0438. \u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0413\u0435\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u043b\u0443\u0436\u0431\u044b \u0421\u0428\u0410, \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0442 \u043e\u043a\u043e\u043b\u043e 24% \u0441\u0435\u0440\u044b \u000d\u000a\u0432 \u043c\u0438\u0440\u0435. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0434\u0435\u0440\u0436\u0430\u0442 \u043d\u0430 \u0441\u043a\u043b\u0430\u0434\u0430\u0445 \u043d\u0435\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u0441\u0435\u0440\u044b, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0445\u0432\u0430\u0442\u0438\u0442 \u043d\u0430 \u043e\u0434\u0438\u043d \u0438\u043b\u0438 \u0434\u0432\u0430 \u043c\u0435\u0441\u044f\u0446\u0430.\u000a\u000d\u000a\u0421 \u0430\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u044b\u043c\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430\u043c\u0438 \u043c\u043e\u0433\u0443\u0442 \u0441\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044c\u0441\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043c\u0435\u0434\u0438 \u0438\u0437 \u0410\u0444\u0440\u0438\u043a\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0432\u0441\u0435 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u044b\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0443\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0431\u0443\u0434\u0443\u0442 \u043a\u043e\u043d\u043a\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0435\u0439 \u0432 \u043f\u043e\u0438\u0441\u043a\u0435 \u000d\u000a\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0441\u0435\u0440\u044b.\u000d\u000a15 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f MMG \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u0442 \u043d\u043e\u0432\u044b\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u000d\u000a\u0432 \u0410\u0444\u0440\u0438\u043a\u0435 \u0438 \u041b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0439 \u0410\u043c\u0435\u0440\u0438\u043a\u0435\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u044c \u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u0439 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u0437\u0430 2025 \u0433\u043e\u0434.\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043d\u0446\u0435\u0440\u043d MMG \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u0439 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u0432\u0435\u0434\u0435\u0442 \u043f\u043e\u0438\u0441\u043a \u043d\u043e\u0432\u044b\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0434\u043b\u044f \u000d\u000a\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044f \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u044f \u0441\u0434\u0435\u043b\u043e\u043a \u0441\u043e \u0441\u043b\u0438\u044f\u043d\u0438\u0435\u043c \u000d\u000a\u0438 \u043f\u043e\u0433\u043b\u043e\u0449\u0435\u043d\u0438\u0435\u043c, \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u0447\u043b\u0435\u043d \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u043e\u0432\u0435\u0442\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0413\u0443\u0430\u043d\u044c \u000d\u000a\u0421\u044f\u043d\u0446\u0437\u044e\u043d\u044c.\u000a\u000d\u000a\u041f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043d\u044b\u0435 \u0440\u0435\u0433\u0438\u043e\u043d\u044b \u0434\u043b\u044f MMG \u2014 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u041b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0439 \u0410\u043c\u0435\u0440\u0438\u043a\u0438 \u0438 \u0410\u0444\u0440\u0438\u043a\u0438. MMG \u0443\u0436\u0435 \u000d\u000a\u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442 \u043e\u0446\u0435\u043d\u043a\u0443 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u044b\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432, \u0438\u0437\u0443\u0447\u0430\u044f \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u044b, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0435\u0449\u0435 \u043d\u0435 \u043d\u0430\u0447\u0430\u043b\u0438 \u0434\u043e\u0431\u044b\u0447\u0443, \u000d\u000a\u043e\u0434\u043d\u0430\u043a\u043e \u043d\u0430\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u043d\u0430 \u043f\u0440\u043e\u0434\u0432\u0438\u043d\u0443\u0442\u043e\u0439 \u0441\u0442\u0430\u0434\u0438\u0438 \u000d\u000a\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438. \u041f\u0440\u0438\u0431\u044b\u043b\u044c MMG \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u043e\u0441\u0442\u0430 \u0446\u0435\u043d \u043d\u0430 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u0431\u043e\u043b\u0435\u0435 \u0447\u0435\u043c \u0432\u0442\u0440\u043e\u0435 \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 \u000d\u000a$509,4 \u043c\u043b\u043d. \u042d\u0442\u043e \u0441\u0442\u0430\u043b\u043e \u0440\u0435\u043a\u043e\u0440\u0434\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0441 2021 \u0433\u043e\u0434\u0430.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a\u0432 2026 \u0433\u043e\u0434\u0443 \u043c\u043e\u0436\u0435\u0442 \u0443\u043f\u0430\u0441\u0442\u044c \u0434\u043e 70%\u000d\u000a\u041d\u0435\u0445\u0432\u0430\u0442\u043a\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b \u0441\u0442\u0430\u043d\u0435\u0442 \u043e\u0449\u0443\u0449\u0430\u0442\u044c\u0441\u044f \u043a \u0438\u044e\u043d\u044e.\u000d\u000a\u041e\u0431\u0449\u0430\u044f \u0441\u0442\u0435\u043f\u0435\u043d\u044c \u0443\u0442\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u0441\u043d\u0438\u0437\u0438\u0442\u044c\u0441\u044f \u0432 2026 \u0433\u043e\u0434\u0443 \u0434\u043e 70%. \u041a\u0430\u043a \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044c \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0438\u043a\u0435\u043b\u044f FINI \u000d\u000a\u0410\u0440\u0438\u0444 \u041f\u0435\u0440\u0434\u0430\u043d\u0430 \u041a\u0443\u0441\u0443\u043c\u0430\u0445, \u044d\u0442\u043e \u0432\u044b\u0437\u0432\u0430\u043d\u043e \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u0438\u0435\u043c \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0441\u0442\u0440\u0430\u043d\u044b \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u000d\u000a\u043a\u0432\u043e\u0442\u044b \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b. \u000a\u000d\u000a\u041f\u043e\u043b\u043d\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0442 340 \u000d\u000a\u0434\u043e 350 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u044d\u0442\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f, \u0432 \u0442\u043e \u0432\u0440\u0435\u043c\u044f \u043a\u0430\u043a \u000d\u000a\u043e\u0431\u0449\u0438\u0439 \u043e\u0431\u044a\u0435\u043c \u043a\u0432\u043e\u0442 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u0440\u0443\u0434\u044b \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u043e \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u000d\u000a\u043e\u0442 260 \u0434\u043e 270 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000d\u000a\u00ab\u041e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0443\u0442\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u0441\u0442\u0430\u043d\u0435\u0442 \u000d\u000a\u0437\u0430\u043c\u0435\u0442\u043d\u044b\u043c \u0432 \u043a\u043e\u043d\u0446\u0435 II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0430 \u044d\u0442\u043e\u0433\u043e \u0433\u043e\u0434\u0430, \u000d\u000a\u043a\u043e\u0433\u0434\u0430 \u043d\u0430\u0447\u043d\u0435\u0442 \u043e\u0449\u0443\u0449\u0430\u0442\u044c\u0441\u044f \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0441\u044b\u0440\u044c\u044f \u2014 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b\u00bb, \u2014 \u043e\u0442\u043c\u0435\u0442\u0438\u043b \u041a\u0443\u0441\u0443\u043c\u0430\u0445.\u000a\u000d\u000aFINI \u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442, \u0447\u0442\u043e \u043d\u0430 \u044d\u0442\u043e\u043c \u0444\u043e\u043d\u0435 \u0438\u043c\u043f\u043e\u0440\u0442 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044e \u0432\u044b\u0440\u0430\u0441\u0442\u0435\u0442 \u000d\u000a\u0441 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e\u0434\u043d\u0438\u0445 15 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0434\u043e 50 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043e\u043a\u043e\u043b\u043e 30 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043e \u0441 \u0424\u0438\u043b\u0438\u043f\u043f\u0438\u043d.\u000d\u000a16 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 6\u201320 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0411\u0440\u0430\u0437\u0438\u043b\u0438\u044f \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0443 \u043f\u0440\u0430\u0432 \u000d\u000a\u043d\u0430 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0437\u043e\u043b\u043e\u0442\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 CMOC Group\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0438\u0437 \u041a\u0438\u0442\u0430\u044f \u043a\u0443\u043f\u0438\u043b\u0430 \u0447\u0435\u0442\u044b\u0440\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0437\u0430 $1 \u043c\u043b\u0440\u0434. \u000d\u000a\u0421\u0443\u0434 \u0432 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0443 \u000d\u000a\u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0438\u0445 \u043a\u0430\u043d\u0430\u0434\u0441\u043a\u043e\u0439 Equinox \u000d\u000aGold \u043f\u0440\u0430\u0432 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u000d\u000a\u0438\u0437 \u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 CMOC Group. \u000a\u000d\u000a\u0412 \u044f\u043d\u0432\u0430\u0440\u0435 \u043a\u0430\u043d\u0430\u0434\u0441\u043a\u0430\u044f Equinox Gold \u0437\u0430\u043a\u0440\u044b\u043b\u0430 \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0443 \u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0435 CMOC \u0447\u0435\u0442\u044b\u0440\u0435\u0445 \u0437\u043e\u043b\u043e\u0442\u044b\u0445 \u000d\u000a\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432 \u0432 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438 \u0437\u0430 $1 \u043c\u043b\u0440\u0434. \u0420\u0435\u0447\u044c \u0448\u043b\u0430 \u000d\u000a\u043e \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u043c \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u0435 Bahia, \u000d\u000a\u0432 \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u0445\u043e\u0434\u044f\u0442 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f Fazenda \u000d\u000a\u0438 Santa Luz (\u0448\u0442\u0430\u0442 \u0411\u0430\u0438\u044f), \u0430 \u0442\u0430\u043a\u0436\u0435 \u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430\u0445 \u000d\u000aAurizona (\u041c\u0430\u0440\u0430\u043d\u044c\u044f\u043d) \u0438 RDM (\u041c\u0438\u043d\u0430\u0441-\u0416\u0435\u0440\u0430\u0439\u0441). \u000d\u000a\u041e\u0434\u043d\u0430\u043a\u043e \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0430\u044f \u0433\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Companhia \u000d\u000aBaiana de Produ\u00e7\u00e3o Mineral (CBPM) \u043e\u0441\u043f\u043e\u0440\u0438\u043b\u0430 \u000d\u000a\u0432 \u0441\u0443\u0434\u0435 \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u0430 Bahia. \u041a\u0430\u043a \u000d\u000a\u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0438\u0441\u0442\u0435\u0446, Equinox Gold Corp \u0431\u044b\u043b\u0430 \u000d\u000a\u0430\u0440\u0435\u043d\u0434\u0430\u0442\u043e\u0440\u043e\u043c, \u0430 \u043d\u0435 \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0435\u043c \u043a\u043e\u043d\u0446\u0435\u0441\u0441\u0438\u0438 \u000d\u000a\u0438 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0435 \u0438\u043c\u0435\u043b\u0430 \u043f\u0440\u0430\u0432\u0430 \u0435\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0442\u044c.\u000a\u000d\u000a\u0421\u0443\u0434 \u043d\u0430\u0437\u043d\u0430\u0447\u0438\u043b \u0437\u0430\u0441\u0435\u0434\u0430\u043d\u0438\u0435 \u043f\u043e \u043f\u0440\u0438\u043c\u0438\u0440\u0435\u043d\u0438\u044e \u000d\u000a\u0441\u0442\u043e\u0440\u043e\u043d \u043d\u0430 30 \u043c\u0430\u0440\u0442\u0430. Equinox Gold \u0432 \u043e\u0442\u0432\u0435\u0442 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430, \u0447\u0442\u043e \u0441\u0434\u0435\u043b\u043a\u0430 \u0443\u0436\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0430 \u0438 \u0431\u044b\u043b\u0430 \u000d\u000a\u043f\u0440\u043e\u0432\u0435\u0434\u0435\u043d\u0430 \u0432 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0441 \u043c\u0435\u0441\u0442\u043d\u044b\u043c \u000d\u000a\u0437\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0443\u0442\u043e\u0447\u043d\u0438\u043b\u0430, \u0447\u0442\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0441\u0443\u0434\u0430 \u0441\u0432\u044f\u0437\u0430\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u0441 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c Santa Luz.\u000d\u000a17 17"]